import numpy as np

ATR_PERIOD = 14
PROFIT_ATR_MULT = 2
ENTRY_SIZE = 0.75          # 75% equity

def strategy(hist, state, pos, ind):
    # -----------------------------------------------------------------
    # 1. State maintenance: if flat but our state says long, clean up
    # -----------------------------------------------------------------
    if pos == 0:
        if state.get('long', 0) == 1:
            # A long trade just ended (stop / cross / take)
            state.pop('entry_price', None)
            state.pop('entry_atr', None)
            state.pop('breakeven_active', None)
            state['long'] = 0

    # -----------------------------------------------------------------
    # 2. When currently long
    # -----------------------------------------------------------------
    if pos > 0:
        # Ensure we have the expected state (should always be the case)
        if state.get('long', 0) != 1:
            # Fallback – shouldn't happen, but try to recover with defaults
            entry_price = state.get('entry_price', hist.close[-1])
            entry_atr = state.get('entry_atr', 1.0)
            breakeven_active = state.get('breakeven_active', 0)
        else:
            entry_price = state['entry_price']
            entry_atr = state['entry_atr']
            breakeven_active = state['breakeven_active']

        macd_line, signal_line, _ = ind.macd(hist.close, 8, 17, 9)
        # Bearish cross: close the position
        if len(macd_line) >= 2 and not np.isnan(macd_line[-2]) and not np.isnan(signal_line[-2]):
            cross_below = (macd_line[-2] >= signal_line[-2] and
                           macd_line[-1] < signal_line[-1])
        else:
            cross_below = False

        if cross_below:
            # Bail out at the next open
            state.pop('entry_price', None)
            state.pop('entry_atr', None)
            state.pop('breakeven_active', None)
            state['long'] = 0
            return {"target": 0.0, "stop": None, "take": None}

        # Ratchet the stop to breakeven if condition met
        if not breakeven_active:
            if hist.close[-1] >= entry_price + PROFIT_ATR_MULT * entry_atr:
                state['breakeven_active'] = 1
                breakeven_active = 1

        stop_price = entry_price if breakeven_active else None
        return {"target": pos, "stop": stop_price, "take": None}

    # -----------------------------------------------------------------
    # 3. Flat: look for a long entry
    # -----------------------------------------------------------------
    # Bullish MACD cross
    macd_line, signal_line, _ = ind.macd(hist.close, 8, 17, 9)
    if len(macd_line) >= 2 and not np.isnan(macd_line[-2]) and not np.isnan(signal_line[-2]):
        cross_above = (macd_line[-2] <= signal_line[-2] and
                       macd_line[-1] > signal_line[-1])
    else:
        cross_above = False

    if not cross_above:
        return {"target": 0.0, "stop": None, "take": None}

    # 60‑minute filter: last completed 60m close > 50‑EMA on 60m
    htf60 = hist.htf(60)
    if len(htf60.close) < 1:
        return {"target": 0.0, "stop": None, "take": None}
    ema60_50 = ind.ema(htf60.close, 50)
    if len(ema60_50) < 1 or np.isnan(ema60_50[-1]):
        return {"target": 0.0, "stop": None, "take": None}
    if htf60.close[-1] <= ema60_50[-1]:
        return {"target": 0.0, "stop": None, "take": None}

    # Entry
    entry_price = hist.close[-1]
    entry_atr = ind.atr(hist, ATR_PERIOD)[-1]
    if np.isnan(entry_atr) or entry_atr <= 0:
        return {"target": 0.0, "stop": None, "take": None}

    state['long'] = 1
    state['entry_price'] = entry_price
    state['entry_atr'] = entry_atr
    state['breakeven_active'] = 0

    return {"target": ENTRY_SIZE, "stop": None, "take": None}

