def strategy(hist, state, pos, ind):
    # Clear state if flat (handles re-entry on the same bar after an exit)
    if pos == 0.0:
        for k in list(state.keys()):
            del state[k]

    # 15-min MACD (5, 35, 5)
    macd_line, signal_line, _ = ind.macd(hist.close, 5, 35, 5)

    # 4h filter: close > 20 EMA
    htf = hist.htf(240)
    if len(htf.close) >= 20:
        ema20_4h = ind.ema(htf.close, 20)
        filter_ok = htf.close[-1] > ema20_4h[-1]
    else:
        filter_ok = False

    # ===== ENTRY WHEN FLAT ====
    if pos == 0.0:
        cross_up = (macd_line[-2] <= signal_line[-2]) and (macd_line[-1] > signal_line[-1])
        if cross_up and filter_ok:
            entry_price = hist.close[-1]
            atr_val = ind.atr(hist, 14)[-1]
            if np.isnan(atr_val) or atr_val <=0:
                return {"target": 0.0, "stop": None, "take": None}

            state['entry_price'] = entry_price
            state['entry_atr'] = atr_val
            state['ratchet_level'] = 0
            state['add_done'] = False

            stop = entry_price - atr_val
            take = entry_price + 2 * atr_val
            return {"target": 0.5, "stop": stop, "take": take}
        else:
            return {"target":0.0, "stop": None, "take": None}

    # ===== IN A TRADE (pos > 0) ====
    # Safety check
    if 'entry_price' not in state:
        return {"target":0.0, "stop": None, "take": None}

    entry_price = state['entry_price']
    entry_atr = state['entry_atr']
    ratchet_level = state['ratchet_level']
    add_done = state['add_done']

    # Exit on oposite MACD cross (bearish crossover)
    cross_down = (macd_line[-2] >= signal_line[-2]) and (macd_line[-1] < signal_line[-1])
    if cross_down:
        for k in list(state.keys()):
            del state[k]
        return {"target": 0.0, "stop": None, "take": None}

    # Size management – pyramid add once
    target = pos
    if not add_done and target < 1.0 - 1e-10:
        if hist.close[-1] >= entry_price + 2 * entry_atr:
            target = min(1.0, target + 0.5)
            state['add_done'] = True

    # Ratchet the trailing box
    profit = hist.close[-1] - entry_price
    if profit > 0:
        new_ratchet = int(profit // entry_atr)
        if new_ratchet > ratchet_level:
            state['ratchet_level'] = new_ratchet
            ratchet_level = new_ratchet

    stop = entry_price - entry_atr + ratchet_level * entry_atr
    take = entry_price + 2 * entry_atr + ratchet_level * entry_atr

    return {"target": target, "stop": stop, "take": take}

