    macd_prev = macd_line[-2]
    macd_curr = macd_line[-1]
    sig_prev = signal_line[-2]
    sig_curr = signal_line[-1]

    # Crossover events (strict definitions)
    bullish_cross = (macd_prev <= sig_prev) and (macd_curr > sig_curr)
    bearish_cross = (macd_prev >= sig_prev) and (macd_curr < sig_curr)

    if pos > 0:
        # We are long
        if bearish_cross:
            # MACD flipped bearish -> bail at the open
            for key in ("entry_price", "entry_atr", "stop_ratcheted"):
                if key in state:
                    del state[key]
            return {"target": 0.0, "stop": None, "take": None}

        # Retrieve trade state
        entry_price = state.get("entry_price")
        entry_atr = state.get("entry_atr")
        stop_ratcheted = state.get("stop_ratcheted", False)

        if entry_price is None or entry_atr is None:
            # Should not happen, but hold position safely
            return {"target": pos, "stop": None, "take": None}

        # Check profit condition: close >= entry + 1.5 * entry ATR
        if not stop_ratcheted and hist.close[-1] >= entry_price + 1.5 * entry_atr:
            stop_ratcheted = True
            state["stop_ratcheted"] = True

        stop = entry_price if stop_ratcheted else None
        return {"target": pos, "stop": stop, "take": None}

    else:
        # Flat: clear any leftover state
        for key in ("entry_price", "entry_atr", "stop_ratcheted"):
            if key in state:
                del state[key]

        if bullish_cross:
            # Enter long with half size (0.5)
            state["entry_price"] = float(hist.close[-1])
            state["entry_atr"] = float(atr[-1])
            state["stop_ratcheted"] = False
            return {"target": 0.5, "stop": None, "take": None}
        else:
            return {"target": 0.0, "stop": None, "take": None}

