import numpy as np

def grid(x):
    """Round to 0.05 grid."""
    return round(x / 0.05) * 0.05

def strategy(hist, state, pos, ind):
    # Current bar index
    t = len(hist) - 1

    # MACD 12,26,9
    macd_line, signal_line, _ = ind.macd(hist.close, 12, 26, 9)
    if t < 1 or np.isnan(macd_line[t]) or np.isnan(signal_line[t]):
        return {"target": pos, "stop": None, "take": None}

    # Cross conditions
    bull_cross = (macd_line[t-1] <= signal_line[t-1] and macd_line[t] > signal_line[t])
    bear_cross = (macd_line[t-1] >= signal_line[t-1] and macd_line[t] < signal_line[t])

    # Trend filter: last completed 60-min close > 20‑period EMA
    htf60 = hist.htf(60)
    trend_up = False
    if len(hf60.close) > 0:
        ema20_60 = ind.ema(hf60.close, 20)
        if len(em20_60) > 0 and not np.isnan(em20_60[-1]):
            trend_up = htf60.close[-1] > ema20_60[-1]

    # 14‑period ATR
    atr = ind.atr(hist, 14)

    if pos == 0.0:
        # Clear any leftover trade state
        for k in ('entry_bar', 'entry_price', 'entry_atr', 'breakeven_active'):
            if k in state:
                del state[k]

        # Only enter when flat
        if bull_cross and trend_up:
            entry_price = hist.close[t]
            entry_atr = atr[t]
            if not np.isnan(entry_atr) and entry_atr > 0:
                state['entry_bar'] = t
                state['entry_price'] = entry_price
                state['entry_atr'] = entry_atr
                state['breakeven_active'] = False
                stop = entry_price - 1.5 * entry_atr
                return {"target": grid(1.0), "stop": stop, "take": None}
        return {"target": 0.0, "stop": None, "take": None}

    # pos > 0 (currently long)
    if 'entry_bar' not in state:
        # Should never happen – force exit
        return {"target": 0.0, "stop": None, "take": None}

    # Exit conditions
    exit_signal = False
    if bear_cross:
        exit_signal = True
    elif t - state['entry_bar'] >= 64:   # time stop
        exit_signal = True

    if exit_signal:
        for k in ('entry_bar', 'entry_price', 'entry_atr', 'breakeven_active'):
            if k in state:
                del state[k]
        return {"target": 0.0, "stop": None, "take": None}

    # Manage trailing stop
    if not state['breakeven_active'] and hist.close[t] >= state['entry_price'] + 2.0 * state['entry_atr']:
        state['breakeven_active'] = True

    if state['breakeven_active']:
        stop = state['entry_price']
    else:
        stop = state['entry_price'] - 1.5 * state['entry_atr']

    # Maintain position
    return {"target": pos, "stop": stop, "take": None}

