import numpy as np

def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    rsi = ind.rsi(hist.close, 14)
    # enough history is guaranteed by warm-up
    curr_rsi = rsi[-1]
    prev_rsi = rsi[-2]
    bull_cross = prev_rsi <= 25 and curr_rsi > 25
    bear_cross = prev_rsi >= 75 and curr_rsi < 75

    # FLAT
    if pos == 0.0:
        # clean up any stale trade state
        for k in ['dir', 'entry_price', 'entry_atr', 'entry_bar', 'ratchet_count', 'stop_price', 'take_price']:
            if k in state:
                del state[k]

        if bull_cross and not bear_cross:
            atr_val = ind.atr(hist, 14)[-1]
            entry_p = hist.close[-1]
            state['dir'] = 1
            state['entry_price'] = entry_p
            state['entry_atr'] = atr_val
            state['entry_bar'] = t
            state['ratchet_count'] = 0
            state['stop_price'] = entry_p - 2 * atr_val
            state['take_price'] = entry_p + 3 * atr_val
            return {"target": 0.75, "stop": state['stop_price'], "take": state['take_price']}

        elif bear_cross and not bull_cross:
            atr_val = ind.atr(hist, 14)[-1]
            entry_p = hist.close[-1]
            state['dir'] = -1
            state['entry_price'] = entry_p
            state['entry_atr'] = atr_val
            state['entry_bar'] = t
            state['ratchet_count'] = 0
            state['stop_price'] = entry_p + 2 * atr_val
            state['take_price'] = entry_p - 3 * atr_val
            return {"target": -0.75, "stop": state['stop_price'], "take": state['take_price']}

        return {"target": pos, "stop": None, "take": None}

    # IN A TRADE
    dir_ = state['dir']

    # opposite RSI crossover closes immediately
    if (dir_ == 1 and bear_cross) or (dir_ == -1 and bull_cross):
        for k in ['dir', 'entry_price', 'entry_atr', 'entry_bar', 'ratchet_count', 'stop_price', 'take_price']:
            if k in state:
                del state[k]
        return {"target": 0.0, "stop": None, "take": None}

    # time exit after 16 bars
    if t - state['entry_bar'] >= 16:
        for k in ['dir', 'entry_price', 'entry_atr', 'entry_bar', 'ratchet_count', 'stop_price', 'take_price']:
            if k in state:
                del state[k]
        return {"target": 0.0, "stop": None, "take": None}

    # ratchet the whole box every time price closes another 2 ATR in profit
    close = hist.close[-1]
    entry_p = state['entry_price']
    atr = state['entry_atr']
    if dir_ == 1:
        while close >= entry_p + (state['ratchet_count'] + 1) * 2 * atr:
            state['ratchet_count'] += 1
            state['stop_price'] += 2 * atr
            state['take_price'] += 2 * atr
    else:  # dir_ == -1
        while close <= entry_p - (state['ratchet_count'] + 1) * 2 * atr:
            state['ratchet_count'] += 1
            state['stop_price'] -= 2 * atr
            state['take_price'] -= 2 * atr

    # maintain position and active exit orders
    return {"target": pos, "stop": state['stop_price'], "take": state['take_price']}

