import numpy as np

def strategy(hist, state, pos, ind):
    """
    Donchian breakout system, 15-minute.
    - 48-bar channel breakout (close > prior 48-bar high or < prior 48-bar low).
    - Volatility sizing: risk 0.5% equity per 2 ATR(14), capped at 1.0, floored at 0.05.
    - Time stop: exit after 32 bars.
    - Opposite signal closes the trade.
    """
    bar = len(hist) - 1
    # Need at least 48 prior bars for the channel
    if bar < 48:
        return {"target": pos, "stop": None, "take": None}

    # Prior 48-bar highest high and lowest low (bars -2 to -49)
    hh = ind.highest(hist.high, 48)
    ll = ind.lowest(hist.low, 48)
    hh_prior = hh[-2]
    ll_prior = ll[-2]

    close = hist.close[-1]
    long_sig = close > hh_prior
    short_sig = close < ll_prior

    # Flat: look for entry
    if pos == 0:
        if long_sig or short_sig:
            atr = ind.atr(hist, 14)[-1]
            if atr > 0:
                fraction = 0.005 * close / (2.0 * atr)
            else:
                fraction = 0.05
            fraction = max(min(fraction, 1.0), 0.05)
            # Round to 0.05 grid
            target = round(fraction * 20.0) / 20.0
            if short_sig:
                target = -target
            state["entry_bar"] = bar
            return {"target": target, "stop": None, "take": None}
        else:
            return {"target": pos, "stop": None, "take": None}

    # In a trade
    exit_trade = False

    # Time stop: exit after 32 bars
    if "entry_bar" in state:
        age = bar - state["entry_bar"]
        if age >= 32:
            exit_trade = True

    # Opposite signal closes the trade
    if pos > 0 and short_sig:
        exit_trade = True
    elif pos < 0 and long_sig:
        exit_trade = True

    if exit_trade:
        return {"target": 0.0, "stop": None, "take": None}
    else:
        return {"target": pos, "stop": None, "take": None}

