import math
import numpy as np


def strategy(hist, state, pos, ind):
    # Start with no change.
    target = pos
    stop = None
    take = None

    # ---- MACD (8, 17, 9) ------------------------------------------------
    macd, sig_line, _ = ind.macd(hist.close, 8, 17, 9)
    if macd.shape[0] < 2:
        return {"target": target, "stop": stop, "take": take}

    macd_prev, macd_curr = float(macd[-2]), float(macd[-1])
    sig_prev, sig_curr = float(sig_line[-2]), float(sig_line[-1])

    if np.isnan(macd_prev) or np.isnan(macd_curr) or np.isnan(sig_prev) or np.isnan(sig_curr):
        return {"target": target, "stop": stop, "take": take}

    # ---- 1‑hour trend filter --------------------------------------------
    htf = hist.htf(60)
    close_1h = hf.close
    ema20_1h = ind.ema(close_1h, 20)

    if close_1h.shape[0] == 0:
        return {"target": target, "stop": stop, "take": take}

    last_close_1h = float(close_1h[-1])
    last_ema20 = float(ema20_1h[-1])

    if np.isnan(last_close_1h) or np.isnan(last_ema20):
        return {"target": target, "stop": stop, "take": take}

    trend_long = last_close_1h > last_ema20
    trend_short = last_close_1h < last_ema20

    # ---- Crosses ------------------------------------------------
    long_cross = (macd_prev <= sig_prev) and (macd_curr > sig_curr)
    short_cross = (macd_prev >= sig_prev) and (macd_curr < sig_curr)

    # ---- Position management ------------------------------------
    if pos == 0.0:
        # Flat – look for entries.
        if long_cross and trend_long:
            target = 0.25
            state['entry_bar'] = len(hist) - 1
        elif short_cross and trend_short:
            target = -0.25
            state['entry_bar'] = len(hist) - 1
    else:
        # In a trade.
        exit_signal = False

        # Opposite signal closes immediately.
        if pos > 0.0 and short_cross:
            target = 0.0
            exit_signal = True
        elif pos < 0.0 and long_cross:
            target = 0.0
            exit_signal = True

        # Time stop: dump after 32 bars (measured from the signal bar).
        if not exit_signal and 'entry_bar' in state:
            bars_since_entry = len(hist) - 1 - state['entry_bar']
            if bars_since_entry >= 32:
                target = 0.0
                exit_signal = True

    # ---- State housekeeping ------------------------------------
    if target == 0.0 and pos != 0.0:   # we just exited
        if 'entry_bar' in state:
            del state['entry_bar']

    # Target must be on the 0.05 grid.
    target = round(target * 20.0) / 20.0

    return {"target": target, "stop": stop, "take": take}

import math
import numpy as np

# Module-level constant for rounding to the 0.05 grid
_GRID_STEP = 0.05

def _round_to_grid(value: float) -> float:
    """Round a target fraction to the nearest 0.05 grid point."""
    return _GRID_STEP * round(value / _GRID_STEP)

def strategy(hist, state, pos, ind) -> dict:
    """
    Long-only breakout-and-retest strategy on BTCUSDT 15-minute bars.
    Implements the trader's instruction exactly.
    """
    t = len(hist) - 1   # current bar index

    # --- Clear trade state when flat (pos == 0.0) ---
    if pos == 0.0 and 'ep' in state:
        for key in ('ep', 'ea', 'hh', 'sd', 'be'):
            state.pop(key, None)

    # --- Indicators (cached by the engine) ---
    atr14 = ind.atr(hist, 14)
    h1 = hist.htf(60)
    if len(h1.close) > 0:
        ema20_h1 = ind.ema(h1.close, 20)
    else:
        ema20_h1 = np.array([])   # safe fallback (should not happen after warm-up)

    # --- Arming the long setup ---
    if not state.get('la', False) and len(hist) > 48:
        high48 = np.max(hist.high[-49:-1])          # prior 48 bars
        if hist.close[-1] > high48:
            state['la'] = True
            state['lab'] = t
            state['lal'] = high48

    # --- Arming the short setup (used only for bail-out) ---
    if not state.get('sa', False) and len(hist) > 48:
        low48 = np.min(hist.low[-49:-1])             # prior 48 bars
        if hist.close[-1] < low48:
            state['sa'] = True
            state['sab'] = t
            state['sal'] = low48

    # --- Disarm on window expiry (16 bars from the signal inclusive) ---
    if state.get('la') and t > state['lab'] + 15:
        state['la'] = False
    if state.get('sa') and t > state['sab'] + 15:
        state['sa'] = False

    # --- 1) Short signal (immediate bail-out if we are long) ---
    if state.get('sa') and t <= state['sab'] + 15 and len(ema20_h1) > 0:
        if hist.high[-1] >= state['sal'] and h1.close[-1] < ema20_h1[-1]:
            state['sa'] = False
            if pos > 0:
                # close whole position
                for k in ('ep', 'ea', 'hh', 'sd', 'be'):
                    state.pop(k, None)
                return {"target": 0.0, "stop": None, "take": None}
            # else flat, just ignore

    # --- 2) Long entry signal ---
    if state.get('la') and t <= state['lab'] + 15 and len(ema20_h1) > 0:
        if hist.low[-1] <= state['lal'] and h1.close[-1] > ema20_h1[-1]:
            state['la'] = False
            if pos == 0.0:
                # enter long with 75% of equity
                entry_price = hist.close[-1]
                entry_atr = atr14[-1]
                highest_high = hist.high[-1]
                state['ep'] = entry_price
                state['ea'] = entry_atr
                state['hh'] = highest_high
                state['sd'] = False
                state['be'] = False

                initial_stop = highest_high - 1.5 * entry_atr
                target = _round_to_grid(0.75)   # 0.75 is already on the grid
                return {"target": target, "stop": initial_stop, "take": None}

    # --- 3) Manage an open long position ---
    if pos > 0 and 'ep' in state:
        ep = state['ep']
        ea = state['ea']
        # update extreme high since entry
        state['hh'] = max(state['hh'], hist.high[-1])
        hh = state['hh']

        # scale out half at +1.5 ATR (inclusive)
        if not state['sd'] and hist.close[-1] >= ep + 1.5 * ea:
            state['sd'] = True

        # activate breakeven stop at +2 ATR (inclusive)
        if not state['be'] and hist.close[-1] >= ep + 2.0 * ea:
            state['be'] = True

        # compute trailing stop
        trail_stop = hh - 1.5 * ea
        if state['be']:
            stop = max(ep, trail_stop)    # tightest of breakeven or trail
        else:
            stop = trail_stop

        # desired size: 0.75 original, 0.40 after scale (0.375 rounded to grid)
        target_size = 0.4 if state['sd'] else 0.75
        target_grid = _round_to_grid(target_size)

        return {"target": target_grid, "stop": stop, "take": None}

    # --- Default: stay flat / maintain current position ---
    return {"target": _round_to_grid(pos), "stop": None, "take": None}

