import numpy as np

def round_to_05(x: float) -> float:
    """Round x to the nearest 0.05 grid."""
    return round(x * 20) / 20


def strategy(hist, state, pos, ind) -> dict:
    t = len(hist) - 1  # index of the current bar

    # ---- indicators ----
    close = hist.close
    sma10 = ind.sma(close, 10)
    sma200 = ind.sma(close, 200)

    sma10_prev = sma10[t - 1] if t >= 1 else np.nan
    sma200_prev = sma200[t - 1] if t >= 1 else np.nan
    sma10_curr = sma10[t]
    sma200_curr = sma200[t]

    # crossing conditions (strict, per desk conventions)
    golden_cross = t >= 1 and sma10_prev <= sma200_prev and sma10_curr > sma200_curr
    death_cross = t >= 1 and sma10_prev >= sma200_prev and sma10_curr < sma200_curr

    # ---- no position: wait for golden cross ----
    if pos == 0.0:
        if golden_cross:
            # record signal-bar state
            state['entry_price'] = float(close[t])
            state['entry_atr'] = float(ind.atr(hist, 14)[t])
            state['entry_bar'] = t
            state['scaled_out'] = False
            return {'target': 0.75, 'stop': None, 'take': None}
        else:
            return {'target': pos, 'stop': None, 'take': None}

    # ---- we hold a long position ----
    # 1) death cross always forces a full exit
    if death_cross:
        state.clear()
        return {'target': 0.0, 'stop': None, 'take': None}

    # 2) manage the trade
    scaled_out = state.get('scaled_out', False)

    if not scaled_out:
        entry_price = state['entry_price']
        entry_atr = state['entry_atr']
        # profit target: 1.5 ATR from entry, inclusive
        if close[t] >= entry_price + 1.5 * entry_atr:
            # scale out to half equity (0.75 /2 = 0.375 -> rounded to grid)
            target = round_to_05(0.375)
            state['scaled_out'] = True
            return {'target': target, 'stop': None, 'take': None}
        else:
            # time exit: 16 bars from the signal bar
            entry_bar = state['entry_bar']
            if t - entry_bar >= 16:
                state.clear()
                return {'target': 0.0, 'stop': None, 'take': None}
            else:
                # hold full position
                return {'target': pos, 'stop': None, 'take': None}
    else:
        # runner: already scaled out, only death cross exits; hold current size
        return {'target': pos, 'stop': None, 'take': None}

