import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ATR_PERIOD = 14
    BOX_BARS = 16
    MAX_BOX_ATR_MULT = 3
    STOP_ATR_MULT = 1
    TIME_STOP_BARS = 32
    POS_SIZE = 0.25

    # Current bar index
    t = len(hist) - 1

    # If flat, clear any stale trade state
    if pos == 0.0:
        for key in ['entry_price', 'entry_atr', 'entry_bar', 'direction']:
            state.pop(key, None)
    else:
        # We are in a trade; ensure state exists (should have been set on entry)
        # If state is missing (should not happen), just hold with no stop
        if 'entry_price' not in state:
            return {"target": pos, "stop": None, "take": None}

    # Compute box from prior 16 bars (indices -17 to -2)
    if len(hist) < BOX_BARS + 1:
        # Not enough data, do nothing
        return {"target": pos, "stop": None, "take": None}

    box_high = np.max(hist.high[-BOX_BARS-1:-1])
    box_low = np.min(hist.low[-BOX_BARS-1:-1])
    box_height = box_high - box_low

    # Current ATR
    atr_val = ind.atr(hist, ATR_PERIOD)[-1]
    if np.isnan(atr_val):
        return {"target": pos, "stop": None, "take": None}

    # Box validity condition
    valid_box = box_height <= MAX_BOX_ATR_MULT * atr_val

    # Current close
    close = hist.close[-1]

    # Entry signals (only when flat)
    if pos == 0.0:
        if valid_box:
            if close > box_high:
                # Long signal
                entry_price = close
                entry_atr = atr_val
                direction = 1
                target = POS_SIZE
                stop = entry_price - STOP_ATR_MULT * entry_atr
                # Save state
                state['entry_price'] = entry_price
                state['entry_atr'] = entry_atr
                state['entry_bar'] = t
                state['direction'] = direction
                return {"target": target, "stop": stop, "take": None}
            elif close < box_low:
                # Short signal
                entry_price = close
                entry_atr = atr_val
                direction = -1
                target = -POS_SIZE
                stop = entry_price + STOP_ATR_MULT * entry_atr
                state['entry_price'] = entry_price
                state['entry_atr'] = entry_atr
                state['entry_bar'] = t
                state['direction'] = direction
                return {"target": target, "stop": stop, "take": None}
        # No signal
        return {"target": pos, "stop": None, "take": None}

    # We are in a trade (pos != 0)
    direction = state['direction']
    entry_price = state['entry_price']
    entry_atr = state['entry_atr']
    entry_bar = state['entry_bar']

    # Check time stop
    age = t - entry_bar
    if age >= TIME_STOP_BARS:
        # Exit at next open
        return {"target": 0.0, "stop": None, "take": None}

    # Check opposite signal
    if valid_box:
        if direction == 1 and close < box_low:
            # Short signal while long -> bail
            return {"target": 0.0, "stop": None, "take": None}
        elif direction == -1 and close > box_high:
            # Long signal while short -> bail
            return {"target": 0.0, "stop": None, "take": None}

    # No exit condition: maintain position with hard stop
    if direction == 1:
        stop = entry_price - STOP_ATR_MULT * entry_atr
    else:
        stop = entry_price + STOP_ATR_MULT * entry_atr

    return {"target": pos, "stop": stop, "take": None}

