    macd, signal_line, _ = ind.macd(hist.close, 12, 26, 9)

    # Safety: if not enough data, do nothing
    if np.isnan(macd[-1]) or np.isnan(macd[-2]) or np.isnan(signal_line[-1]) or np.isnan(signal_line[-2]):
        return {"target": pos, "stop": None, "take": None}

    # Cross conditions
    cross_up = (macd[-2] <= signal_line[-2]) and (macd[-1] > signal_line[-1])
    cross_down = (macd[-2] >= signal_line[-2]) and (macd[-1] < signal_line[-1])

    # 1‑hour filter: last completed 1h close > 50 EMA on 1h
    htf = hist.htf(60)
    hf_ok = False
    if len(htf) >= 50:
        ema50 = ind.ema(htf.close, 50)
        if not np.isnan(ema50[-1]) and htf.close[-1] > ema50[-1]:
            hf_ok = True

    # ----- FLAT STATE -----
    if pos == 0.0:
        if cross_up and hf_ok:
            entry_price = float(hist.close[-1])
            atr_series = ind.atr(hist, 14)
            entry_atr = float(atr_series[-1])
            if np.isnan(entry_atr):
                return {"target": 0.0, "stop": None, "take": None}
            state["entry_price"] = entry_price
            state["entry_atr"] = entry_atr
            state["breakeven_trig"] = False
            state["add_count"] = 0
            state["last_add_price"] = entry_price
            state["active"] = True
            return {"target": 0.25, "stop": None, "take": None}
        else:
            return {"target": 0.0, "stop": None, "take": None}

    # ----- LONG POSITION -----
    # We are long; check if we have a managed trade (active flag)
    if not state.get("active", False):
        return {"target": pos, "stop": None, "take": None}

    # Exit on opposite signal
    if cross_down:
        state["active"] = False
        return {"target": 0.0, "stop": None, "take": None}

    entry_price = state["entry_price"]
    entry_atr = state["entry_atr"]
    breakeven_trig = state["breakeven_trig"]
    add_count = state["add_count"]
    last_add_price = state["last_add_price"]

    # Breakeven stop logic
    if not breakeven_trig:
        if hist.close[-1] >= entry_price + 0.5 * entry_atr:
            breakeven_trig = True
            state["breakeven_trig"] = True

    stop = entry_price if breakeven_trig else None

    # Default: keep current position
    target = pos

    # Pyramid: one add of 0.25 when price moves >= 1 ATR in favour from last add
    if add_count == 0 and abs(pos - 0.25) < 1e-9:
        if hist.close[-1] >= last_add_price + entry_atr:
            target = 0.5
            state["last_add_price"] = float(hist.close[-1])
            state["add_count"] = 1

    return {"target": target, "stop": stop, "take": None}

