def strategy(hist, state, pos, ind):
    # Clean up trade state when flat
    if pos == 0:
        for key in ('entry_bar', 'entry_price', 'entry_atr', 'direction', 'scaled_out', 'extreme'):
            state.pop(key, None)

    # Indicators
    atr = ind.atr(hist, 14)
    htf60 = hist.htf(60)
    htf60_close = htf60.close
    ema_1h_50 = ind.ema(htf60_close, 50)

    highest20 = ind.highest(hist.high, 20)
    lowest20 = ind.lowest(hist.low, 20)
    prior_high = highest20[-2]
    prior_low = lowest20[-2]
    close = hist.close[-1]

    # Entry / opposite signal conditions
    long_cond = (close > prior_high) and (htf60_close[-1] > ema_1h_50[-1])
    short_cond = (close < prior_low) and (htf60_close[-1] < ema_1h_50[-1])

    # Flat: look for new trade
    if pos == 0:
        if long_cond:
            state['entry_bar'] = len(hist) - 1
            state['entry_price'] = close
            state['entry_atr'] = atr[-1]
            state['direction'] = 1
            state['scaled_out'] = False
            state['extreme'] = hist.high[-1]
            target = 0.25
            return {"target": round(target * 20) / 20, "stop": None, "take": None}
        elif short_cond:
            state['entry_bar'] = len(hist) - 1
            state['entry_price'] = close
            state['entry_atr'] = atr[-1]
            state['direction'] = -1
            state['scaled_out'] = False
            state['extreme'] = hist.low[-1]
            target = -0.25
            return {"target": round(target * 20) / 20, "stop": None, "take": None}
        else:
            return {"target": 0.0, "stop": None, "take": None}

    # In a trade
    entry_bar = state['entry_bar']
    entry_price = state['entry_price']
    entry_atr = state['entry_atr']
    direction = state['direction']
    scaled_out = state['scaled_out']
    extreme = state['extreme']

    # Update extreme price since entry
    if direction == 1:
        extreme = max(extreme, hist.high[-1])
    else:
        extreme = min(extreme, hist.low[-1])
    state['extreme'] = extreme

    # Opposite signal -> close immediately
    if (direction == 1 and short_cond) or (direction == -1 and long_cond):
        return {"target": 0.0, "stop": None, "take": None}

    # Time stop after 32 bars
    bars_held = len(hist) - 1 - entry_bar
    if bars_held == 32:
        return {"target": 0.0, "stop": None, "take": None}

    # Scale-out logic
    if not scaled_out:
        if direction == 1:
            if close >= entry_price + 2 * entry_atr:
                scaled_out = True
                state['scaled_out'] = True
                target = 0.125
            else:
                target = pos
        else:  # direction == -1
            if close <= entry_price - 2 * entry_atr:
                scaled_out = True
                state['scaled_out'] = True
                target = -0.125
            else:
                target = pos
    else:
        target = pos

    # Trailing stop (only after scaling out)
    stop = None
    if scaled_out:
        if direction == 1:
            stop = extreme - 3 * entry_atr
        else:
            stop = extreme + 3 * entry_atr

    return {"target": round(target * 20) / 20, "stop": stop, "take": None}

import math
import numpy as np

RSI_LEN = 21
ATR_LEN = 14
RSI_LOW = 20.0
RSI_HIGH = 80.0
RISK = 0.005
STOP_ATR = 2.0
TAKE_ATR = 4.0
MAX_BARS = 32
MIN_TARGET = 0.05
MAX_TARGET = 1.0

def clamp_size(value):
    if value < 0.0:
        value = -value
    return min(max(value, MIN_TARGET), MAX_TARGET)

def clear_trade_state(state):
    for key in ("entry_bar", "entry_price", "entry_atr", "dir"):
        if key in state:
            del state[key]

def strategy(hist, state, pos, ind) -> dict:
    t = len(hist) - 1

    if pos != 0.0:
        if not ("entry_bar" in state and "entry_price" in state and "entry_atr" in state and "dir" in state):
            clear_trade_state(state)
            return {"target": 0.0, "stop": None, "take": None}

        if t - state["entry_bar"] >= MAX_BARS:
            clear_trade_state(state)
            return {"target": 0.0, "stop": None, "take": None}

        rsi = ind.rsi(hist.close, RSI_LEN)
        rsi_prev = rsi[-2]
        rsi_curr = rsi[-1]
        long_sig = rsi_prev <= RSI_LOW and rsi_curr > RSI_LOW
        short_sig = rsi_prev >= RSI_HIGH and rsi_curr < RSI_HIGH

        if (pos > 0.0 and short_sig) or (pos < 0.0 and long_sig):
            clear_trade_state(state)
            return {"target": 0.0, "stop": None, "take": None}

        entry_price = state["entry_price"]
        entry_atr = state["entry_atr"]
        direction = state["dir"]

        if direction > 0:
            stop = entry_price - STOP_ATR * entry_atr
            take = entry_price + TAKE_ATR * entry_atr
        else:
            stop = entry_price + STOP_ATR * entry_atr
            take = entry_price - TAKE_ATR * entry_atr

        return {"target": pos, "stop": stop, "take": take}

    rsi = ind.rsi(hist.close, RSI_LEN)
    rsi_prev = rsi[-2]
    rsi_curr = rsi[-1]
    long_sig = rsi_prev <= RSI_LOW and rsi_curr > RSI_LOW
    short_sig = rsi_prev >= RSI_HIGH and rsi_curr < RSI_HIGH

    if not (long_sig or short_sig):
        return {"target": 0.0, "stop": None, "take": None}

    entry_price = float(hist.close[-1])
    atr = float(ind.atr(hist, ATR_LEN)[-1])

    if math.isnan(atr) or atr <= 0.0:
        atr = 0.0
        size = MIN_TARGET
    else:
        size = clamp_size(RISK * entry_price / atr)

    if long_sig:
        direction = 1
        target = size
        stop = entry_price - STOP_ATR * atr
        take = entry_price + TAKE_ATR * atr
    else:
        direction = -1
        target = -size
        stop = entry_price + STOP_ATR * atr
        take = entry_price - TAKE_ATR * atr

    state["entry_bar"] = t
    state["entry_price"] = entry_price
    state["entry_atr"] = atr
    state["dir"] = direction

    return {"target": target, "stop": stop, "take": take}

