SCALE_ATR = 3.0
COLDOWN = 4
TIME_LIMIT = 32

def strategy(hist, state, pos, ind):
    i = len(hist) - 1                     # current bar index
    # MACD
    macd_line, signal_line, _ = ind.macd(hist.close, FAST, SLOW, SIG)
    curr_macd = float(macd_line[-1])
    prev_macd = float(macd_line[-2])
    curr_sig = float(signal_line[-1])
    prev_sig = float(signal_line[-2])
    # ATR
    atr = ind.atr(hist, ATR_PERIOD)
    curr_atr = float(atr[-1])

    in_trade = state.get('in_trade', False)

    if in_trade:
        # Check if we just exited (pos went to zero)
        if abs(pos) < 1e-8:
            state['exit_bar'] = i
            state['in_trade'] = False
            return {"target": 0.0, "stop": None, "take": None}

        # 1. Bearish MACD crossover kills the long
        if prev_macd >= prev_sig and curr_macd < curr_sig:
            return {"target": 0.0, "stop": None, "take": None}

        # 2. Scale out to half when full size is >= 3 ATR in profit
        if not state.get('scaled_out', False) and abs(pos - 0.25) < 1e-8:
            if hist.close[-1] >= state['entry_price'] + SCALE_ATR * state['entry_atr']:
                state['scaled_out'] = True
                return {"target": 0.125, "stop": None, "take": None}

        # 3. Time exit – 32 bars since the entry signal
        sig_bar = state.get('signal_bar', -1)
        if sig_bar != -1 and i == sig_bar + TIME_LIMIT:
            return {"target": 0.0, "stop": None, "take": None}

        # Maintain current position
        return {"target": pos, "stop": None, "take": None}

    else:
        # Flat – check entry conditions
        exit_bar = state.get('exit_bar', -1)
        # Cooldown of 4 bars since last exit
        if i > exit_bar + COLDOWN:
            # Bullish MACD crossover
            if prev_macd <= prev_sig and curr_macd > curr_sig:
                state['in_trade'] = True
                state['entry_price'] = float(hist.close[-1])
                state['entry_atr'] = float(curr_atr)
                state['signal_bar'] = i
                state['scaled_out'] = False
                return {"target": 0.25, "stop": None, "take": None}

        return {"target": 0.0, "stop": None, "take": None}

