    prev_ema50 = ema50[-2]

    cross_up = (prev_ema20 <= prev_ema50 and cur_ema20 > cur_ema50)
    cross_down = (prev_ema20 >= prev_ema50 and cur_ema20 < cur_ema50)

    close = hist.close[-1]

    if pos == 0.0:
        # Clean any trade state just in case
        for k in ('entry_price', 'entry_atr', 'direction', 'ratchet_step', 'entry_bar'):
            if k in state:
                del state[k]

        if cross_up:
            entry_price = close
            entry_atr = atr[-1]
            raw_target_abs = 0.01 * entry_price / (2.0 * entry_atr)
            abs_target = max(0.05, min(1.0, raw_target_abs))
            target = round(abs_target / 0.05) * 0.05

            state['entry_price'] = float(entry_price)
            state['entry_atr'] = float(entry_atr)
            state['direction'] = 1
            state['ratchet_step'] = 0
