            stop = entry_price - 2.0 * entry_atr
            take = entry_price + 3.0 * entry_atr
            return {"target": target, "stop": stop, "take": take}

        elif cross_down:
            entry_price = close
            entry_atr = atr[-1]
            raw_target_abs = 0.01 * entry_price / (2.0 * entry_atr)
            abs_target = max(0.05, min(1.0, raw_target_abs))
            target = -round(abs_target / 0.05) * 0.05

            state['entry_price'] = float(entry_price)
            state['entry_atr'] = float(entry_atr)
            state['direction'] = -1
            state['ratchet_step'] = 0
            state['entry_bar'] = len(hist) - 1

            stop = entry_price + 2.0 * entry_atr
            take = entry_price - 3.0 * entry_atr
            return {"target": target, "stop": stop, "take": take}

        else:
            return {"target": 0.0, "stop": None, "take": None}

    # In a trade
    if 'entry_price' not in state:
        # Position exists but no trade state – close to be safe
        return {"target": 0.0, "stop": None, "take": None}

