    entry_atr = state['entry_atr']
    direction = state['direction']
    ratchet_step = state['ratchet_step']
    entry_bar = state['entry_bar']
    current_bar = len(hist) - 1

    # Opposite crossover closes trade
    if direction == 1 and cross_down:
        for k in ('entry_price', 'entry_atr', 'direction', 'ratchet_step', 'entry_bar'):
            if k in state:
                del state[k]
        return {"target": 0.0, "stop": None, "take": None}
    if direction == -1 and cross_up:
        for k in ('entry_price', 'entry_atr', 'direction', 'ratchet_step', 'entry_bar'):
            if k in state:
                del state[k]
        return {"target": 0.0, "stop": None, "take": None}

    # Time exit after 128 bars
    if current_bar - entry_bar >= 128:
        for k in ('entry_price', 'entry_atr', 'direction', 'ratchet_step', 'entry_bar'):
            if k in state:
                del state[k]
        return {"target": 0.0, "stop": None, "take": None}

    # Ratchet step based on profit milestones
    if direction == 1:
        milestone = entry_price + 2.0 * (ratchet_step + 1) * entry_atr
        if close >= milestone:
            ratchet_step += 1
            state['ratchet_step'] = ratchet_step
        stop = entry_price + (2.0 * ratchet_step - 2.0) * entry_atr
        take = entry_price + (3.0 + 2.0 * ratchet_step) * entry_atr
