        raw_target = 0.005 * close / (3.0 * atr_val)
        target = max(0.05, min(1.0, raw_target))
        if bear_cross:
            target = -target

        # Round to 0.05 grid
        target = round(target * 20.0) / 20.0
        target = max(-1.0, min(1.0, target))  # safety clamp

