import math
import numpy as np

def round_to_05(x: float) -> float:
    """Round to nearest 0.05."""
    return round(x * 20.0) / 20.0

def strategy(hist, state, pos, ind) -> dict:
    """
    Oversold bounce / overbought fade mean reversion using 14-period RSI.

    Entry:
        Long when RSI crosses back up through 30 (prev <=30, curr >30).
        Short when RSI crosses back down through 70 (prev >=70, curr <70).
    Sizing: risk 1% equity per 2 ATR (14-period).
    Exits: trailing hard stop (4*entry_ATR behind extreme price),
            128-bar time stop, or opposite RSI crossover.
    """
    t = len(hist) - 1                      # current bar index

    # ---- indicators ------------------------------------------------------------
    atr_arr = ind.atr(hist, 14)             # 14-period ATR
    atr = float(atr_arr[-1])
    rsi_arr = ind.rsi(hist.close, 14)       # 14-period RSI
    rsi_curr = float(rsi_arr[-1])
    rsi_prev = float(rsi_arr[-2]) if len(rsi_arr) >= 2 else math.nan

    # Crossover conditions
    long_sig = False
    short_sig = False
    if not math.isnan(rsi_prev):
        long_sig = (rsi_prev <= 30.0 and rsi_curr > 30.0)
        short_sig = (rsi_prev >= 70.0 and rsi_curr < 70.0)

    # ---- flat: clean stale state and look for entry --------------- -- ---
    if pos == 0.0:
        # Remove any stale trade data
        for k in ('entry_bar', 'entry_atr', 'extreme'):
            if k in state:
                del state[k]

        if atr <= 1e-12:
            return {"target": 0.0, "stop": None, "take": None}

        if long_sig:
            raw_target = 0.01 * hist.close[-1] / (2.0 * atr)
            target = round_to_05(raw_target)
            target = min(1.0, max(0.0, target))
            if target <= 0.0:
                return {"target": 0.0, "stop": None, "take": None}
            state['entry_bar'] = t
            state['entry_atr'] = atr
            state['extreme'] = hist.close[-1]          # start extreme at signal close
            stop = state['extreme'] - 4.0 * atr
            return {"target": target, "stop": stop, "take": None}

        if short_sig:
            raw_target = 0.01 * hist.close[-1] / (2.0 * atr)
            target = -round_to_05(raw_target)
            target = max(-1.0, min(0.0, target))
            if target >= 0.0:
                return {"target": 0.0, "stop": None, "take": None}
            state['entry_bar'] = t
            state['entry_atr'] = atr
            state['extreme'] = hist.close[-1]
            stop = state['extreme'] + 4.0 * atr
            return {"target": target, "stop": stop, "take": None}

        return {"target": 0.0, "stop": None, "take": None}

    # ---- we hold a position -----------------------------------------------------
    if 'entry_bar' not in state:
        # should not happen, but safe fallback
        return {"target": pos, "stop": None, "take": None}

    entry_bar = int(state['entry_bar'])
    entry_atr = float(state['entry_atr'])

    # 128-bar time stop
    if t - entry_bar >= 128:
        return {"target": 0.0, "stop": None, "take": None}

    # opposite crossover signal
    if pos > 0.0 and short_sig:
        return {"target": 0.0, "stop": None, "take": None}
    if pos < 0.0 and long_sig:
        return {"target": 0.0, "stop": None, "take": None}

    # update extreme and trailing stop
    if pos > 0.0:
        extreme = max(float(state['extreme']), hist.high[-1])
        state['extreme'] = extreme
        stop = extreme - 4.0 * entry_atr
        return {"target": pos, "stop": stop, "take": None}
    else:  # pos < 0
        extreme = min(float(state['extreme']), hist.low[-1])
        state['extreme'] = extreme
        stop = extreme + 4.0 * entry_atr
        return {"target": pos, "stop": stop, "take": None}

