def strategy(hist, state, pos, ind):
    # Need at least 18 bars to look back 16 bars prior to current (indices -17..-2)
    if len(hist) < 18:
        return {"target": 0.0, "stop": None, "take": None}

    # Current ATR on 15‑minute bars
    atr = ind.atr(hist, 14)[-1]

    # 16‑bar Donchian channel: highest high and lowest low of the PRIOR 16 bars (excludes current)
    box_high = np.max(hist.high[-17:-1])
    box_low   = np.min(hist.low[-17:-1])
    height    = box_high - box_low

    signal_dir = 0

    if height <= 6 * atr:
        close = hist.close[-1]
        long_break  = close > box_high
        short_break = close < box_low

        if long_break or short_break:
            h1h = hist.htf(60)
            if len(h1h.close) > 0:
                last_h1_close = h1h.close[-1]
                ema_h1 = ind.ema(h1h.close, 20)[-1]

                if long_break and last_h1_close > ema_h1:
                    signal_dir = 1
                elif short_break and last_h1_close < ema_h1:
                    signal_dir = -1

    # ----- flat -----
    if pos == 0.0:
        if signal_dir != 0:
            target = 0.5 * signal_dir   # +0.5 long, -0.5 short
            state['entry_price'] = hist.close[-1]
            state['entry_atr']   = atr
            state['dir']         = signal_dir
            take = hist.close[-1] + (2 * atr if signal_dir == 1 else -2 * atr)
            return {"target": target, "stop": None, "take": take}
        else:
            return {"target": 0.0, "stop": None, "take": None}

    # ----- in a trade -----
    cur_dir = state.get('dir', 0)

    # opposite signal flips the position
    if signal_dir != 0 and signal_dir != cur_dir:
        target = 0.5 * signal_dir
        state['entry_price'] = hist.close[-1]
        state['entry_atr']   = atr
        state['dir']         = signal_dir
        take = hist.close[-1] + (2 * atr if signal_dir == 1 else -2 * atr)
        return {"target": target, "stop": None, "take": take}

    # maintain current trade – send the take‑profit order
    entry_price = state['entry_price']
    entry_atr   = state['entry_atr']
    if cur_dir == 1:
        take = entry_price + 2 * entry_atr
    else:
        take = entry_price - 2 * entry_atr

    return {"target": pos, "stop": None, "take": take}

