    bear_cross = ema10[-2] >= ema100[-2] and ema10[-1] < ema100[-1]

    # Entry logic (only when flat)
    if pos == 0:
        if bull_cross:
            state['direction'] = 1
            state['entry_price'] = close[-1]
            state['entry_atr'] = atr[-1]
            state['adds'] = 0
            state['last_add_price'] = close[-1]
            state['signal_bar'] = t
            return {"target": 0.25, "stop": None, "take": None}
        if bear_cross:
            state['direction'] = -1
            state['entry_price'] = close[-1]
            state['entry_atr'] = atr[-1]
            state['adds'] = 0
            state['last_add_price'] = close[-1]
            state['signal_bar'] = t
            return {"target": -0.25, "stop": None, "take": None}
        return {"target": 0.0, "stop": None, "take": None}

    # We are in a trade; state must exist
    if 'direction' not in state:
        return {"target": pos, "stop": None, "take": None}

    direction = state['direction']

    # Exit: opposite crossover
    if direction == 1 and bear_cross:
        return {"target": 0.0, "stop": None, "take": None}
    if direction == -1 and bull_cross:
        return {"target": 0.0, "stop": None, "take": None}

    # Exit: time stop (128 bars since signal bar)
    if t - state['signal_bar'] >= 128:
        return {"target": 0.0, "stop": None, "take": None}

    # Pyramiding: up to 2 adds, each after 1 ATR move from last add price
    if state['adds'] < 2:
        if direction == 1:
            if close[-1] >= state['last_add_price'] + state['entry_atr']:
                new_adds = state['adds'] + 1
                target = 0.25 * (1 + new_adds)
                state['adds'] = new_adds
                state['last_add_price'] = close[-1]
                return {"target": target, "stop": None, "take": None}
        else:  # direction == -1
            if close[-1] <= state['last_add_price'] - state['entry_atr']:
                new_adds = state['adds'] + 1
                target = -0.25 * (1 + new_adds)
                state['adds'] = new_adds
                state['last_add_price'] = close[-1]
                return {"target": target, "stop": None, "take": None}

    # No change
    return {"target": pos, "stop": None, "take": None}

