    """
    # Constants
    RSI_PERIOD = 7
    ATR_PERIOD = 14
    ATR_MULT = 2
    RISK_PCT = 0.005
    CAP = 1.0
    FLOOR = 0.05
    GRID = 0.05
    COOLDOWN_MS = 4 * 3600 * 1000  # 4 hours in ms
    EMA_4H_PERIOD = 50
    HTF_MINUTES = 240

    # ---- Indicators ----
    rsi_series = ind.rsi(hist.close, RSI_PERIOD)
    if len(rsi_series) < 2:
        return {"target": pos, "stop": None, "take": None}
