    atr_val = ind.atr(hist, ATR_PERIOD)[-1]
    if avg_val <= 0 or math.isnan(avg_val):
        # fallback to current bar range if ATTR fails (should not happen)
        atr_val = hist.high[-1] - hist.low[-1]

    # 4h filter
    h4 = hist.htf(HTF_MINUTES)
    filter_long = False
    filter_short = False
    if len(h4.close) >= EMA_4H_PERIOD:
        ema_h4 = ind.ema(h4.close, EMA_4H_PERIOD)[-1]
        h4_close = h4.close[-1]
        if not (math.isnan(ema_h4) or math.isnan(h4_close)):
            filter_long = h4_close > ema_h4
            filter_short = h4_close < ema_h4

    # Signals
    long_sig = (rsi_prev <= 30 and rsi_val > 30 and filter_long)
    short_sig = (rsi_prev >= 70 and rsi_val < 70 and filter_short)

    # ---- Exit detection (went flat) ----
    if pos == 0 and state.get("dir", 0) != 0:
        # Trade just ended -> record cooldown time
        state["last_exit_time"] = hist.time[-1]
        # Clean up trade state
        for k in ("dir", "entry_atr", "extreme", "init_extreme"):
            if k in state:
                del state[k]

    # ---- Fl at: process new entries ----
    if pos == 0:
        if not (long_sig or short_sig):
            return {"target": 0.0, "stop": None, "take": None}

        current_time = hist.time[-1]
        # Cooldown
        last_exit = state.get("last_exit_time", 0)
        if last_exit and (current_time - last_exit) < COOLDOWN_MS:
            return {"target": 0.0, "stop": None, "take": None}
        # Daily limit
        current_day = current_time // (24 * 3600 * 1000)
        last_entry_day = state.get("last_entry_day", -1)
        if current_day == last_entry_day:
            return {"target": 0.0, "stop": None, "take": None}

        # Size
        raw_frac = RISK_PCT * hist.close[-1] / (ATR_MULT * atr_val)
        raw_frac = max(FLOOR, min(CAP, raw_frac))
        target_abs = round(raw_frac / GRID) * GRID
        target_abs = max(FLOOR, min(CAP, target_abs))  # just in case

        if long_sig:
            target = target_abs
            state["dir"] = 1
        else:
            target = -target_abs
            state["dir"] = -1

        state["entry_atr"] = atr_val
        state["init_extreme"] = True
        state["last_entry_day"] = current_day

        # Initial stop
        entry_price = hist.close[-1]
        if state["dir"] == 1:
            stop = entry_price - ATR_MULT * atr_val
        else:
            stop = entry_price + ATR_MULT * atr_val

        return {"target": target, "stop": stop, "take": None}

    # ---- Hold or flip a position ----
    dir = state.get("dir")
    if dir is None:
        dir = 1 if pos > 0 else -1  # recovery

    # Update extreme price
    if state.get("init_extreme", False):
        if dir == 1:
            state["extreme"] = hist.high[-1]
        else:
            state["extreme"] = hist.low[-1]
