        if dir == 1:
            if hist.high[-1] > state["extreme"]:
                state["extreme"] = hist.high[-1]
        else:
            if hist.low[-1] < state["extreme"]:
                state["extreme"] = hist.low[-1]

    entry_atr = state.get("entry_atr", atr_val)
    if dir == 1:
        stop = state["extreme"] - ATR_MULT * entry_atr
    else:
        stop = state["extreme"] + ATR_MULT * entry_atr

    # Opposite signal --- flip
    if (dir == 1 and short_sig) or (dir == -1 and long_sig):
        # Recalculate size with current ATR
        if atr_val <= 0:
            return {"target": pos, "stop": stop, "take": None}
