        if new_dir == 1:
            new_stop = entry_price - ATR_MULT * atr_val
        else:
            new_stop = entry_price + ATR_MULT * atr_val

        return {"target": new_target, "stop": new_stop, "take": None}

    # No flip --- keep position
    return {"target": pos, "stop": stop, "take": None}

