    # Opposite signal -> bail immediately
    if direction == 1 and short_signal:
        return {"target": 0.0, "stop": None, "take": None}
    if direction == -1 and long_signal:
        return {"target": 0.0, "stop": None, "take": None}

    # Time stop after 128 bars
    if t - state['entry_bar'] >= 128:
        return {"target": 0.0, "stop": None, "take": None}

    # Update extreme price since entry
    if direction == 1:
        state['extreme'] = max(state['extreme'], hist.high[-1])
    else:
        state['extreme'] = min(state['extreme'], hist.low[-1])

    # Breakeven ratchet: activate once a candle closes 1.5 ATR in profit
    if not state['breakeven']:
        if direction == 1:
            if hist.close[-1] - state['entry_price'] >= 1.5 * state['entry_atr']:
                state['breakeven'] = True
        else:
            if state['entry_price'] - hist.close[-1] >= 1.5 * state['entry_atr']:
                state['breakeven'] = True

    # Trailing stop: 2 ATR behind the extreme, ratcheted to breakeven if applicable
    if direction == 1:
        stop = state['extreme'] - 2 * state['entry_atr']
        if state['breakeven']:
            stop = max(state['entry_price'], stop)
    else:
        stop = state['extreme'] + 2 * state['entry_atr']
        if state['breakeven']:
            stop = min(state['entry_price'], stop)

    return {"target": pos, "stop": stop, "take": None}

