    i = len(hist) - 1                           # current bar index
    current_day = int(hist.time[i] // 86400000)   # UTC day number

    # ── daily entry cap reset ───────────────────────────────────────────
    last_day = state.get('last_day', -1)
    if current_day != last_day:
        state['last_day'] = current_day
        state['daily_entries'] = 0

    # ── FLAT ───────────────────────────────────────────
    if pos == 0.0:
        # clear any stale trade state
        for k in ['entry_bar', 'entry_atr', 'last_add_price', 'adds']:
            state.pop(k, None)

        if i < 1:
            return {"target": 0.0, "stop": None, "take": None}

        macd_line, signal_line, _ = ind.macd(hist.close, 5, 35, 5)
        # bullish crossover
        if macd_line[i-1] <= signal_line[i-1] and macd_line[i] > signal_line[i]:
            daily_entries = state.get('daily_entries', 0)
            if daily_entries < 2:
                atr = ind.atr(hist, 14)
                entry_atr = atr[i]
                state['daily_entries'] = daily_entries + 1
                state['entry_bar'] = i
                state['entry_atr'] = entry_atr
                state['last_add_price'] = hist.close[i]
                state['adds'] = 0
                return {"target": 0.25, "stop": None, "take": None}

        return {"target": pos, "stop": None, "take": None}

    # ── IN POSITION (LONG) ───────────────────────────
    if pos > 0:
        entry_bar   = state.get('entry_bar')
        entry_atr   = state.get('entry_atr')
        last_add    = state.get('last_add_price')
        adds        = state.get('adds', 0)

        # safety – should never happen after a clean state reset
        if entry_bar is None:
            return {"target": pos, "stop": None, "take": None}

        macd_line, signal_line, _ = ind.macd(hist.close, 5, 35, 5)

        # 1. bearish crossover → bail at next open
        if i >= 1 and macd_line[i-1] >= signal_line[i-1] and macd_line[i] < signal_line[i]:
            for k in ['entry_bar', 'entry_atr', 'last_add_price', 'adds']:
                state.pop(k, None)
            return {"target": 0.0, "stop": None, "take": None}

        # 2. time stop: 32 bars since the signal bar
        if i - entry_bar >= 32:
            for k in ['entry_bar', 'entry_atr', 'last_add_price', 'adds']:
                state.pop(k, None)
            return {"target": 0.0, "stop": None, "take": None}

        # 3. pyramiding adds
        if adds < 2 and hist.close[i] >= last_add + 2 * entry_atr:
            adds += 1
            state['adds'] = adds
            state['last_add_price'] = hist.close[i]
            new_target = min(0.25 * (1 + adds), 0.75)   # max full size = 0.75
            return {"target": new_target, "stop": None, "take": None}

        # no action – keep current position
        return {"target": pos, "stop": None, "take": None}

    # fallback (should never be reached)
    return {"target": pos, "stop": None, "take": None}

