import numpy as np

def strategy(hist, state, pos, ind):
    # Constants
    FAST = 5
    SLOW = 35
    SIGNAL = 5
    ATR_PERIOD = 14
    EMA_PERIOD = 20
    POS_SIZE = 0.75
    PROFIT_ATR = 1.5

    # If flat, clear any leftover trade state (except daily cap)
    if pos == 0.0:
        for key in ("entry_price", "entry_atr", "stop_level"):
            if key in state:
                del state[key]
    else:
        # We are in a trade; state must contain entry info
        if "entry_price" not in state:
            # Should not happen, but safely do nothing
            return {"target": pos, "stop": None, "take": None}

    # Compute MACD
    macd_line, signal_line, _ = ind.macd(hist.close, FAST, SLOW, SIGNAL)
    if len(macd_line) < 2 or np.isnan(macd_line[-1]) or np.isnan(signal_line[-1]):
        return {"target": pos, "stop": None, "take": None}

    # Current UTC day for daily trade cap
    current_day = hist.time[-1] // 86400000  # ms to days

    # ------------------------------------------------------------------
    # In a long trade
    # ------------------------------------------------------------------
    if pos > 0.0:
        # 1) Bearish MACD crossover -> exit at next open
        if macd_line[-2] >= signal_line[-2] and macd_line[-1] < signal_line[-1]:
            for key in ("entry_price", "entry_atr", "stop_level"):
                if key in state:
                    del state[key]
            return {"target": 0.0, "stop": None, "take": None}

        # 2) Ratchet stop to breakeven once 1.5 ATR in profit
        entry_price = state["entry_price"]
        entry_atr = state["entry_atr"]
        stop_level = state.get("stop_level", 0.0)

        if stop_level == 0.0 and hist.close[-1] >= entry_price + PROFIT_ATR * entry_atr:
            stop_level = entry_price
            state["stop_level"] = stop_level

        # Maintain position with current stop (if any)
        return {
            "target": pos,
            "stop": stop_level if stop_level > 0.0 else None,
            "take": None
        }

    # ------------------------------------------------------------------
    # Flat – look for a new entry
    # ------------------------------------------------------------------
    # Daily cap: only one entry per UTC calendar day
    last_entry_day = state.get("last_entry_day", -1)
    if current_day == last_entry_day:
        return {"target": 0.0, "stop": None, "take": None}

    # Trend filter: last completed 1h close > 20 EMA on 1h
    htf = hist.htf(60)
    if len(htf.close) < EMA_PERIOD:
        return {"target": 0.0, "stop": None, "take": None}
    ema20 = ind.ema(htf.close, EMA_PERIOD)
    if len(ema20) == 0 or np.isnan(ema20[-1]) or htf.close[-1] <= ema20[-1]:
        return {"target": 0.0, "stop": None, "take": None}

    # Bullish MACD crossover
    if macd_line[-2] <= signal_line[-2] and macd_line[-1] > signal_line[-1]:
        entry_price = hist.close[-1]
        entry_atr = ind.atr(hist, ATR_PERIOD)[-1]
        if np.isnan(entry_atr):
            return {"target": 0.0, "stop": None, "take": None}

        state["entry_price"] = entry_price
        state["entry_atr"] = entry_atr
        state["stop_level"] = 0.0
        state["last_entry_day"] = current_day
        return {"target": POS_SIZE, "stop": None, "take": None}

    # No signal
    return {"target": 0.0, "stop": None, "take": None}

