def strategy(hist, state, pos, ind) -> dict:
    # Need at least 21 bars for prior 20-bar high/low
    if len(hist) < 21:
        return {"target": 0.0, "stop": None, "take": None}

    # Prior 20-bar high and low (bars -21 to -2)
    prior_high = ind.highest(hist.high, 20)[-2]
    prior_low  = ind.lowest(hist.low, 20)[-2]

    # Current 14-bar ATR
    atr = ind.atr(hist, 14)[-1]

    # Daily entry counter
    day_idx = int(hist.time[-1] // (24 * 3600 * 1000))
    if 'day' not in state or state['day'] != day_idx:
        state['day'] = day_idx
        state['entries_today'] = 0

    # If a stop/take closed the position, clear trade state
    if pos == 0.0 and state.get('in_trade', False):
        for key in ('in_trade', 'entry_price', 'entry_atr', 'ratchets', 'breakeven'):
            if key in state:
                del state[key]

    # --- FLAT ---
    if pos == 0.0:
        # Long entry: close > prior 20-bar high, max 3 entries per day
        if hist.close[-1] > prior_high and state.get('entries_today', 0) < 3:
            entry_price = float(hist.close[-1])
            entry_atr   = float(atr)
            state['in_trade']    = True
            state['entry_price'] = entry_price
            state['entry_atr']   = entry_atr
            state['ratchets']    = 0
            state['breakeven']   = False
            state['entries_today'] = state.get('entries_today', 0) + 1

            stop = entry_price - entry_atr
            take = entry_price + 2 * entry_atr
            return {"target": 0.75, "stop": stop, "take": take}
        else:
            return {"target": 0.0, "stop": None, "take": None}

    # --- IN A LONG POSITION ---
    if pos > 0.0:
        if not state.get('in_trade', False):
            # State lost – safety exit
            return {"target": 0.0, "stop": None, "take": None}

        # Bearish 20-bar breakdown -> immediate exit
        if hist.close[-1] < prior_low:
            for key in ('in_trade', 'entry_price', 'entry_atr', 'ratchets', 'breakeven'):
                if key in state:
                    del state[key]
            return {"target": 0.0, "stop": None, "take": None}

        entry_price = state['entry_price']
        entry_atr   = state['entry_atr']
        ratchets    = state['ratchets']
        breakeven   = state['breakeven']

        # Breakeven trigger: close >= entry + 1.5 ATR
        if not breakeven and hist.close[-1] >= entry_price + 1.5 * entry_atr:
            breakeven = True
            state['breakeven'] = True

        # Ratchet: every additional 2 ATR above entry
        while hist.close[-1] >= entry_price + 2 * (ratchets + 1) * entry_atr:
            ratchets += 1
        state['ratchets'] = ratchets

        # Compute stop and take
        base_stop = entry_price + (2 * ratchets - 1) * entry_atr
        if breakeven:
            stop = max(entry_price, base_stop)
        else:
            stop = base_stop
        take = entry_price + (2 * ratchets + 2) * entry_atr

        return {"target": pos, "stop": stop, "take": take}

    # Fallback (should not be reached)
    return {"target": 0.0, "stop": None, "take": None}

