    # If flat, remove any leftover trade state
    if pos == 0:
        for k in ('entry_price', 'entry_atr', 'scaled'):
            if k in state:
                del state[k]

    # 32-bar box: highest high and lowest low of the prior 32 bars (excluding current)
    prior_high = np.max(hist.high[-33:-1])
    prior_low = np.min(hist.low[-33:-1])
    box_height = prior_high - prior_low

    # Current 14-period ATR
    atr_val = ind.atr(hist, 14)[-1]
    if np.isnan(atr_val):
        atr_val = 0.0  # safety fallback, no signal

    # Breakout conditions (box height must be ≤ 6 ATR)
    long_signal = (hist.close[-1] > prior_high) and (box_height <= 6 * atr_val)
    short_signal = (hist.close[-1] < prior_low) and (box_height <= 6 * atr_val)

    target = pos
    stop = None
    take = None

    if pos == 0:
        # Flat: enter if daily entry limit not reached
        if state['entries_today'] < 3:
            if long_signal:
                target = 0.75
                state['entry_price'] = hist.close[-1]
                state['entry_atr'] = atr_val
                state['scaled'] = False
                state['entries_today'] += 1
            elif short_signal:
                target = -0.75
                state['entry_price'] = hist.close[-1]
                state['entry_atr'] = atr_val
                state['scaled'] = False
                state['entries_today'] += 1
    else:
        # In a position: reversal signal takes precedence
        if (pos > 0 and short_signal) or (pos < 0 and long_signal):
            target = 0.0
            for k in ('entry_price', 'entry_atr', 'scaled'):
                if k in state:
                    del state[k]
        else:
            entry_price = state.get('entry_price')
            entry_atr = state.get('entry_atr')
            scaled = state.get('scaled', False)
            if entry_price is not None and entry_atr is not None:
                if not scaled:
                    # Scale out half when 1.5 ATR in profit on a bar close
                    if pos > 0 and hist.close[-1] >= entry_price + 1.5 * entry_atr:
                        new_target = pos / 2.0
                        target = round(new_target / 0.05) * 0.05
                        if pos > 0 and target < 0:
                            target = 0.0
                        elif pos < 0 and target > 0:
                            target = 0.0
                        state['scaled'] = True
                    elif pos < 0 and hist.close[-1] <= entry_price - 1.5 * entry_atr:
                        new_target = pos / 2.0
                        target = round(new_target / 0.05) * 0.05
                        if pos > 0 and target < 0:
                            target = 0.0
                        elif pos < 0 and target > 0:
                            target = 0.0
                        state['scaled'] = True
                if state.get('scaled', False):
                    # Hard take-profit at 2 ATR from entry
                    if pos > 0:
                        take = entry_price + 2.0 * entry_atr
                    elif pos < 0:
                        take = entry_price - 2.0 * entry_atr

    return {"target": target, "stop": stop, "take": take}

