def strategy(hist, state, pos, ind):
    # Retrieve previous position to detect exits
    prev_pos = state.get('prev_pos', 0.0)
    exit_occurred = False

    # Detect an exit: position went from >0 to 0 (stop/take fill or our own exit signal)
    if pos == 0.0 and prev_pos > 0.0:
        state['cooldown'] = 16
        exit_occurred = True

    # Decrement cooldown when flat, but not on the very bar we just set it
    if pos == 0.0 and state.get('cooldown', 0) > 0 and not exit_occurred:
        state['cooldown'] -= 1

    # Compute EMAs
    ema5 = ind.ema(hist.close, 5)
    ema50 = ind.ema(hist.close, 50)
    ema5_curr = ema5[-1]
    ema5_prev = ema5[-2]
    ema50_curr = ema50[-1]
    ema50_prev = ema50[-2]

    # Crossover definitions (strict)
    bullish_cross = (ema5_prev <= ema50_prev) and (ema5_curr > ema50_curr)
    bearish_cross = (ema5_prev >= ema50_prev) and (ema5_curr < ema50_curr)

    if pos > 0.0:
        # Currently long
        if bearish_cross:
            # Exit at next open
            state['prev_pos'] = pos
            return {"target": 0.0, "stop": None, "take": None}
        else:
            # Manage stop loss
            entry_price = state.get('entry_price', None)
            entry_atr = state.get('entry_atr', None)
            breakeven_activated = state.get('breakeven_activated', False)

            if entry_price is None or entry_atr is None:
                stop = None
            else:
                # Check breakeven condition: close >= entry + 2 * ATR
                if not breakeven_activated and hist.close[-1] >= entry_price + 2 * entry_atr:
                    breakeven_activated = True
                    state['breakeven_activated'] = True

                if breakeven_activated:
                    stop = entry_price
                else:
                    stop = entry_price - entry_atr

            state['prev_pos'] = pos
            return {"target": pos, "stop": stop, "take": None}
    else:
        # Flat
        if state.get('cooldown', 0) > 0:
            state['prev_pos'] = pos
            return {"target": 0.0, "stop": None, "take": None}

        if bullish_cross:
            entry_price = hist.close[-1]
            atr_val = ind.atr(hist, 14)[-1]
            if atr_val <= 0:
                state['prev_pos'] = pos
                return {"target": 0.0, "stop": None, "take": None}

            # Volatility sizing: risk 0.5% per 1 ATR
            fraction = 0.005 * entry_price / atr_val
            clamped = max(0.05, min(1.0, fraction))
            target = round(clamped * 20) / 20
            # Ensure target stays within bounds after rounding
            if target < 0.05:
                target = 0.05
            elif target > 1.0:
                target = 1.0

            # Store trade parameters
            state['entry_price'] = entry_price
            state['entry_atr'] = atr_val
            state['breakeven_activated'] = False

            stop = entry_price - atr_val
            state['prev_pos'] = pos
            return {"target": target, "stop": stop, "take": None}
        else:
            state['prev_pos'] = pos
            return {"target": 0.0, "stop": None, "take": None}

