        else:
            # Update trailing extreme and stop
            if pos > 0:
                extreme = state.get('extreme', hist.high[-1])
                extreme = max(extreme, hist.high[-1])
            else:
                extreme = state.get('extreme', hist.low[-1])
                extreme = min(extreme, hist.low[-1])
            state['extreme'] = extreme
