    def cross_above(prev_short, prev_long, curr_short, curr_long):
        return (not np.isnan(prev_short) and not np.isnan(prev_long) and
                prev_short <= prev_long and curr_short > curr_long)

    def cross_below(prev_short, prev_long, curr_short, curr_long):
        return (not np.isnan(prev_short) and not np.isnan(prev_long) and
                prev_short >= prev_long and curr_short < curr_long)

    # Current bar index is -1, previous is -2
    golden = cross_above(sma5[-2], sma100[-2], sma5[-1], sma100[-1])
    death = cross_below(sma5[-2], sma100[-2], sma5[-1], sma100[-1])

    # -----------------------------------------------------------------
    # In a long trade
    if pos > 0:
        # Ensure state consistency (should already be set)
        if not state.get('in_trade', False):
            # If for some reason state is missing, reset to flat
            return {"target": 0.0, "stop": None, "take": None}

        # Update highest high since entry
        if not state.get('first_bar_done', False):
            state['highest_high'] = hist.high[-1]
            state['first_bar_done'] = True
        else:
            if hist.high[-1] > state['highest_high']:
                state['highest_high'] = hist.high[-1]

        # Death cross exit while in profit
        if death and hist.close[-1] >= state['entry_price']:
            # Clean up state
            for k in ('in_trade', 'entry_atr', 'entry_price', 'highest_high', 'first_bar_done'):
                if k in state:
                    del state[k]
            return {"target": 0.0, "stop": None, "take": None}

        # Trailing stop: 4 ATR below highest high
        stop_price = state['highest_high'] - 4.0 * state['entry_atr']
        return {"target": pos, "stop": stop_price, "take": None}

    # -----------------------------------------------------------------
    # In a short trade (should not happen, but exit if it does)
    elif pos < 0:
        return {"target": 0.0, "stop": None, "take": None}

    # -----------------------------------------------------------------
    # Flat
    else:
        # Clean up any leftover state from a previous trade
        if state.get('in_trade', False):
            for k in ('in_trade', 'entry_atr', 'entry_price', 'highest_high', 'first_bar_done'):
                if k in state:
                    del state[k]

        # Golden cross entry
        if golden:
            state['in_trade'] = True
            state['entry_atr'] = atr[-1]          # ATR on the signal bar
            state['entry_price'] = hist.close[-1] # entry price = signal bar close
            state['first_bar_done'] = False       # will be set on the first bar of the trade
            target = round(1.0 * 20) / 20         # 1.0 on the 0.05 grid
            return {"target": target, "stop": None, "take": None}

        # No signal
        return {"target": 0.0, "stop": None, "take": None}

