        if cross_up and entries_today < 3:
            target = 0.5
            state['dir'] = 1
            state['entry_price'] = float(hist.close[-1])
            state['entry_atr'] = float(ind.atr(hist, 14)[-1])
            state['added'] = 0
            state['entries_today'] = entries_today + 1
            return {"target": target, "stop": None, "take": None}

        if cross_down and entries_today < 3:
            target = -0.5
            state['dir'] = -1
            state['entry_price'] = float(hist.close[-1])
            state['entry_atr'] = float(ind.atr(hist, 14)[-1])
            state['added'] = 0
            state['entries_today'] = entries_today + 1
            return {"target": target, "stop": None, "take": None}

        return {"target": 0.0, "stop": None, "take": None}

    # In a trade
    dir = state.get('dir')
    if dir is None:  # safety, should not happen
        return {"target": pos, "stop": None, "take": None}

    entry_price = state['entry_price']
    entry_atr = state['entry_atr']
    added = bool(state.get('added', 0))

    # Opposite signal closes the trade
    if dir == 1 and cross_down:
        for k in ['dir', 'entry_price', 'entry_atr', 'added']:
            state.pop(k, None)
        return {"target": 0.0, "stop": None, "take": None}
    if dir == -1 and cross_up:
        for k in ['dir', 'entry_price', 'entry_atr', 'added']:
            state.pop(k, None)
        return {"target": 0.0, "stop": None, "take": None}

    # Pyramiding: add half size if price moved 2 ATR in our favour (max 1 add)
    if not added:
        if dir == 1 and hist.close[-1] >= entry_price + 2 * entry_atr:
            target = 1.0
            state['added'] = 1
            return {"target": target, "stop": None, "take": None}
        if dir == -1 and hist.close[-1] <= entry_price - 2 * entry_atr:
            target = -1.0
            state['added'] = 1
            return {"target": target, "stop": None, "take": None}

    # Maintain current position
    return {"target": pos, "stop": None, "take": None}

