        # ----- opposite signal closes the trade -----
        opposite_signal = False
        if armed_bars > 0 and armed_dir == -trade_dir:
            touch = False
            if armed_dir == 1:                     # long setup retest
                if hist.low[-1] <= state['armed_level']:
                    touch = True
            else:                                   # short setup retest
                if hist.high[-1] >= state['armed_level']:
                    touch = True
            if touch:
                if armed_dir == 1:
