                        stop = state['extreme'] + 4 * state['entry_atr']
                else:
                    target = 1.0 * trade_dir
            else:
                # already scaled out – maintain half size with trailing stop
                target = 0.5 * trade_dir
                if trade_dir == 1:
                    stop = state['extreme'] - 4 * state['entry_atr']
                else:
                    stop = state['extreme'] + 4 * state['entry_atr']

    else:
        # ----- flat: look for an entry -----
        armed_bars = state.get('armed_bars_left', 0)
        if armed_bars > 0:
            armed_dir = state.get('armed_dir', 0)
            touch = False
            if armed_dir == 1:
                if hist.low[-1] <= state['armed_level']:
