                    target = 1.0 * trade_dir
                    # stop / take remain None

    # ----- decrement armed period -----
    if 'armed_bars_left' in state and state['armed_bars_left'] > 0:
        state['armed_bars_left'] -= 1

    # round target to 0.05 grid
    target = round(target * 20) / 20.0
    return {"target": target, "stop": stop, "take": take}

