def strategy(hist, state, pos, ind) -> dict:
    # RSI(7) for mean reversion signals
    rsi = ind.rsi(hist.close, 7)
    if len(rsi) < 2:
        # Not enough data for a cross, maintain current position
        return {"target": pos, "stop": None, "take": None}

    # Current UTC day from the bar's open time (ms since epoch)
    current_day = hist.time[-1] // 86400000

    # Initialize / update daily entry counter
    day = state.get("day", -1)
    entries = state.get("entries", 0)
    if current_day != day:
        day = current_day
        entries = 0
        state["day"] = day
        state["entries"] = entries

    # Signal definitions (cross events)
    long_signal = rsi[-2] <= 25 and rsi[-1] > 25
    short_signal = rsi[-2] >= 75 and rsi[-1] < 75

    # Flat: only enter if daily cap not reached
    if pos == 0.0:
        if long_signal and entries < 3:
            entries += 1
            state["entries"] = entries
            return {"target": 0.75, "stop": None, "take": None}
        if short_signal and entries < 3:
            entries += 1
            state["entries"] = entries
            return {"target": -0.75, "stop": None, "take": None}
        # No valid entry signal or cap reached
        return {"target": 0.0, "stop": None, "take": None}

    # In a long position: opposite signal closes it
    if pos > 0.0:
        if short_signal:
            return {"target": 0.0, "stop": None, "take": None}
        return {"target": pos, "stop": None, "take": None}

    # In a short position: opposite signal closes it
    if pos < 0.0:
        if long_signal:
            return {"target": 0.0, "stop": None, "take": None}
        return {"target": pos, "stop": None, "take": None}

    # Fallback (should never be reached)
    return {"target": pos, "stop": None, "take": None}

