import numpy as np

def strategy(hist, state, pos, ind):
    i = len(hist) - 1

    # ----- indicators -----
    sma10 = ind.sma(hist.close, 10)
    sma200 = ind.sma(hist.close, 200)
    atr = ind.atr(hist, 14)
    htf = hist.htf(60)
    htf_ema50 = ind.ema(htf.close, 50)

    # ----- cross detection -----
    cross_up = False
    cross_down = False
    if i >= 1:
        s10_prev, s200_prev = sma10[-2], sma200[-2]
        s10_curr, s200_curr = sma10[-1], sma200[-1]
        if not (np.isnan(s10_prev) or np.isnan(s200_prev) or
                np.isnan(s10_curr) or np.isnan(s200_curr)):
            if s10_prev <= s200_prev and s10_curr > s200_curr:
                cross_up = True
            elif s10_prev >= s200_prev and s10_curr < s200_curr:
                cross_down = True

    # ----- 1h filter -----
    long_filter = False
    short_filter = False
    if len(htf.close) > 0 and len(htf_ema50) > 0:
        htf_close = htf.close[-1]
        htf_ema = htf_ema50[-1]
        if not (np.isnan(htf_close) or np.isnan(htf_ema)):
            if htf_close > htf_ema:
                long_filter = True
            elif htf_close < htf_ema:
                short_filter = True

    # ----- cooldown after a flat -----
    cooldown = False
    if 'flat_bar' in state:
        if i - state['flat_bar'] <= 16:
            cooldown = True

    # ----- in a trade -----
    if state.get('in_trade', False):
        # stopped out during this bar?
        if pos == 0.0:
            state['flat_bar'] = i
            for key in ('in_trade', 'entry_price', 'entry_atr', 'direction', 'breakeven_done'):
                if key in state:
                    del state[key]
            return {"target": 0.0, "stop": None, "take": None}

        direction = state['direction']

        # opposite cross closes the trade
        if (direction == 1 and cross_down) or (direction == -1 and cross_up):
            return {"target": 0.0, "stop": None, "take": None}

        entry_price = state['entry_price']
        entry_atr = state['entry_atr']
        breakeven_done = state.get('breakeven_done', False)

        # check 2 ATR profit condition
        if not breakeven_done:
            if direction == 1:
                if hist.close[-1] >= entry_price + 2 * entry_atr:
                    breakeven_done = True
                    state['breakeven_done'] = True
            else:  # short
                if hist.close[-1] <= entry_price - 2 * entry_atr:
                    breakeven_done = True
                    state['breakeven_done'] = True

        # set stop
        if breakeven_done:
            stop = entry_price
        else:
            if direction == 1:
                stop = entry_price - entry_atr
            else:
                stop = entry_price + entry_atr

        # maintain position
        return {"target": pos, "stop": stop, "take": None}

    # ----- flat -----
    if not cooldown:
        if cross_up and long_filter:
            entry_price = hist.close[-1]
            entry_atr = atr[-1]
            state['in_trade'] = True
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['direction'] = 1
            state['breakeven_done'] = False
            stop = entry_price - entry_atr
            return {"target": 0.75, "stop": stop, "take": None}

        if cross_down and short_filter:
            entry_price = hist.close[-1]
            entry_atr = atr[-1]
            state['in_trade'] = True
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['direction'] = -1
            state['breakeven_done'] = False
            stop = entry_price + entry_atr
            return {"target": -0.75, "stop": stop, "take": None}

    return {"target": 0.0, "stop": None, "take": None}

