import numpy as np

def strategy(hist, state, pos, ind):
    """
    Donchian breakout and retest strategy on 15-minute bars.
    Trades both ways with fixed size of 1 unit.
    """
    t = len(hist) - 1

    # --- initialize persistent state ---
    if 'dir' not in state:
        state['dir'] = 0            # 1 = long, -1 = short, 0 = flat
        state['entry_price'] = 0.0
        state['entry_atr'] = 0.0
        state['scaled_out'] = False
        state['long_armed'] = False
        state['long_armed_bar'] = 0
        state['long_level'] = 0.0
        state['short_armed'] = False
        state['short_armed_bar'] = 0
        state['short_level'] = 0.0

    # if position was closed by a stop/take, reset trade state
    if pos == 0.0 and state['dir'] != 0:
        state['dir'] = 0
        state['entry_price'] = 0.0
        state['entry_atr'] = 0.0
        state['scaled_out'] = False

    # --- prior 48-bar high / low (the 48 bars BEFORE the current bar) ---
    prior_high = None
    prior_low = None
    if t >= 48:
        prior_high = max(hist.high[t-48:t])
        prior_low = min(hist.low[t-48:t])

    # --- 4h conditions ---
    htf = hist.htf(240)
    long_4h_ok = False
    short_4h_ok = False
    if len(htf.close) > 0:
        htf_close = htf.close[-1]
        htf_ema20 = ind.ema(htf.close, 20)[-1]
        if not np.isnan(htf_ema20):
            long_4h_ok = htf_close > htf_ema20
            short_4h_ok = htf_close < htf_ema20

    # --- arm setups on breakout closes ---
    if prior_high is not None:
        if not state['long_armed'] and hist.close[-1] > prior_high:
            state['long_armed'] = True
            state['long_armed_bar'] = t
            state['long_level'] = prior_high
        if not state['short_armed'] and hist.close[-1] < prior_low:
            state['short_armed'] = True
            state['short_armed_bar'] = t
            state['short_level'] = prior_low

    # --- expire armed setups after 8 bars (signal bar + 7 more) ---
    if state['long_armed'] and t > state['long_armed_bar'] + 7:
        state['long_armed'] = False
    if state['short_armed'] and t > state['short_armed_bar'] + 7:
        state['short_armed'] = False

    # --- trigger detection (wick + 4h filter) ---
    long_signal = False
    short_signal = False
    if state['long_armed'] and t <= state['long_armed_bar'] + 7:
        if hist.low[-1] <= state['long_level'] and long_4h_ok:
            long_signal = True
    if state['short_armed'] and t <= state['short_armed_bar'] + 7:
        if hist.high[-1] >= state['short_level'] and short_4h_ok:
            short_signal = True

    # --- act according to current position ---
    if pos == 0.0:
        # flat – only enter on a signal
        if long_signal and not short_signal:
            state['dir'] = 1
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = ind.atr(hist, 14)[-1]
            state['scaled_out'] = False
            return {"target": 1.0, "stop": None, "take": None}
        elif short_signal and not long_signal:
            state['dir'] = -1
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = ind.atr(hist, 14)[-1]
            state['scaled_out'] = False
            return {"target": -1.0, "stop": None, "take": None}
        else:
            return {"target": 0.0, "stop": None, "take": None}

    elif pos > 0:
        # long position
        if short_signal:
            # opposite signal closes the trade
            state['dir'] = 0
            state['entry_price'] = 0.0
            state['entry_atr'] = 0.0
            state['scaled_out'] = False
            return {"target": 0.0, "stop": None, "take": None}

        entry_price = state['entry_price']
        entry_atr = state['entry_atr']
        if not state['scaled_out'] and hist.close[-1] >= entry_price + 2 * entry_atr:
            # scale out: half position, stop to breakeven
            state['scaled_out'] = True
            return {"target": 0.5, "stop": entry_price, "take": None}
        elif state['scaled_out']:
            return {"target": 0.5, "stop": entry_price, "take": None}
        else:
            return {"target": 1.0, "stop": None, "take": None}

    else:  # pos < 0 – short position
        if long_signal:
            # opposite signal closes the trade
            state['dir'] = 0
            state['entry_price'] = 0.0
            state['entry_atr'] = 0.0
            state['scaled_out'] = False
            return {"target": 0.0, "stop": None, "take": None}

        entry_price = state['entry_price']
        entry_atr = state['entry_atr']
        if not state['scaled_out'] and hist.close[-1] <= entry_price - 2 * entry_atr:
            state['scaled_out'] = True
            return {"target": -0.5, "stop": entry_price, "take": None}
        elif state['scaled_out']:
            return {"target": -0.5, "stop": entry_price, "take": None}
        else:
            return {"target": -1.0, "stop": None, "take": None}

