    if 'cooldown' not in state:
        state['cooldown'] = 0
        state['entry_price'] = 0.0
        state['entry_atr'] = 0.0
        state['added'] = False
        state['breakeven'] = False

    # Detect trade just ended (position became flat)
    if pos == 0.0 and state['entry_price'] != 0.0:
        state['cooldown'] = 4
        state['entry_price'] = 0.0
        state['entry_atr'] = 0.0
        state['added'] = False
        state['breakeven'] = False
    elif pos == 0.0 and state['cooldown'] > 0:
        state['cooldown'] -= 1

    # Entry logic (only when flat and cooldown expired)
    if pos == 0.0 and state['cooldown'] == 0:
        # Long: RSI crosses up through 30
        if prev_rsi <= 30.0 and curr_rsi > 30.0:
            state['entry_price'] = close
            state['entry_atr'] = curr_atr
            state['added'] = False
            state['breakeven'] = False
            stop = close - 1.5 * curr_atr
            return {"target": 0.5, "stop": stop, "take": None}
        # Short: RSI crosses down through 70
        if prev_rsi >= 70.0 and curr_rsi < 70.0:
            state['entry_price'] = close
            state['entry_atr'] = curr_atr
            state['added'] = False
            state['breakeven'] = False
            stop = close + 1.5 * curr_atr
            return {"target": -0.5, "stop": stop, "take": None}

    # In-trade management
    if pos != 0.0:
        entry_price = state['entry_price']
        entry_atr = state['entry_atr']
        added = state['added']
        breakeven = state['breakeven']
        direction = 1 if pos > 0 else -1

        # Opposite signal closes the trade
        if direction == 1:
            if prev_rsi >= 70.0 and curr_rsi < 70.0:
                return {"target": 0.0, "stop": None, "take": None}
        else:
            if prev_rsi <= 30.0 and curr_rsi > 30.0:
                return {"target": 0.0, "stop": None, "take": None}

        # Move stop to breakeven once 2 ATR in profit on a close
        if not breakeven:
            if direction == 1:
                if close >= entry_price + 2 * entry_atr:
                    breakeven = True
                    state['breakeven'] = True
            else:
                if close <= entry_price - 2 * entry_atr:
                    breakeven = True
                    state['breakeven'] = True

        # Determine current stop level
        if breakeven:
            stop = entry_price
        else:
            if direction == 1:
                stop = entry_price - 1.5 * entry_atr
            else:
                stop = entry_price + 1.5 * entry_atr

        # Pyramid add: once 2 ATR in favour from entry, add another 0.5 (max 1 add)
        if not added:
            if direction == 1:
                if close >= entry_price + 2 * entry_atr:
                    state['added'] = True
                    return {"target": 1.0, "stop": stop, "take": None}
            else:
                if close <= entry_price - 2 * entry_atr:
                    state['added'] = True
                    return {"target": -1.0, "stop": stop, "take": None}

        # Maintain current position with stop
        return {"target": pos, "stop": stop, "take": None}

    # Flat and no entry signal
    return {"target": pos, "stop": None, "take": None}

