    # Detect when we become flat (position just closed)
    if pos == 0.0 and state['prev_pos'] != 0.0:
        state['last_flat_bar'] = bar_index

    # Update UTC day and reset daily entry counter if day changed
    bar_time = hist.time[-1]
    day = bar_time // 86400000  # ms -> UTC day number
    if day != state['current_day']:
