        be_triggered = state.get('be_triggered', False)
        extreme = state.get('extreme', 0.0)

        # check breakeven trigger (2 ATR profit on close)
        if not be_triggered:
            if direction == 1:
                profit = hist.close[-1] - entry_price
            else:
                profit = entry_price - hist.close[-1]
            if profit >= 2 * entry_atr:
                be_triggered = True
                state['be_triggered'] = True
                # start tracking extreme from this bar
                if direction == 1:
                    extreme = hist.high[-1]
                else:
                    extreme = hist.low[-1]
                state['extreme'] = extreme
        else:
            # update extreme
            if direction == 1:
                extreme = max(extreme, hist.high[-1])
            else:
                extreme = min(extreme, hist.low[-1])
            state['extreme'] = extreme

        # compute stop
        if not be_triggered:
            if direction == 1:
                stop = entry_price - 2 * entry_atr
            else:
                stop = entry_price + 2 * entry_atr
        else:
            if direction == 1:
                stop = max(entry_price, extreme - 2 * entry_atr)
            else:
                stop = min(entry_price, extreme + 2 * entry_atr)

        return {'target': pos, 'stop': stop, 'take': None}

    # --- flat: look for entry ---
    if long_sig or short_sig:
        if state['entries_today'] >= 2:
            return {'target': 0.0, 'stop': None, 'take': None}

        direction = 1 if long_sig else -1
        atr_val = ind.atr(hist, 14)[-1]
        close_price = hist.close[-1]

        # volatility sizing: risk 1% per 2 ATR
        raw = 0.005 * close_price / atr_val   # 0.01 / 2 = 0.005
        fraction = max(0.05, min(1.0, raw))
        fraction = round(fraction * 20) / 20   # 0.05 grid
        fraction = max(0.05, min(1.0, fraction))

        target = fraction if direction == 1 else -fraction

        state['dir'] = direction
        state['entry_price'] = close_price
        state['entry_atr'] = atr_val
        state['be_triggered'] = False
        state['extreme'] = 0.0
        state['entries_today'] += 1

        if direction == 1:
            stop = close_price - 2 * atr_val
        else:
            stop = close_price + 2 * atr_val

        return {'target': target, 'stop': stop, 'take': None}

    # no signal
    return {'target': 0.0, 'stop': None, 'take': None}

