                state['scaled_out'] = False
        return {"target": target, "stop": None, "take": None}

    # In a position
    # Opposite signal flattens immediately
    if (pos > 0 and close < bottom) or (pos < 0 and close > top):
        for k in ('entry_price', 'entry_atr', 'scaled_out'):
            if k in state:
                del state[k]
        return {"target": 0.0, "stop": None, "take": None}

    # Check scale-out condition (once per trade)
    if not state.get('scaled_out', False):
        entry_price = state['entry_price']
        entry_atr = state['entry_atr']
        if pos > 0:
            profit_atr = (close - entry_price) / entry_atr
        else:
            profit_atr = (entry_price - close) / entry_atr

        if profit_atr >= 1.5:
