    return {"target": pos, "stop": None, "take": None}

import math
import numpy as np

def strategy(hist, state, pos, ind):
    # Need at least two bars for crossover
    if len(hist.close) < 2:
        return {"target": pos, "stop": None, "take": None}

    # 20/50 EMA on 15m close
    ema20 = ind.ema(hist.close, 20)
    ema50 = ind.ema(hist.close, 50)
    if np.isnan(ema20[-1]) or np.isnan(ema50[-1]) or np.isnan(ema20[-2]) or np.isnan(ema50[-2]):
        return {"target": pos, "stop": None, "take": None}

    ema20_prev = ema20[-2]
    ema50_prev = ema50[-2]
    ema20_curr = ema20[-1]
    ema50_curr = ema50[-1]

    cross_up = (ema20_prev <= ema50_prev) and (ema20_curr > ema50_curr)
    cross_down = (ema20_prev >= ema50_prev) and (ema20_curr < ema50_curr)

    # 1h trend filter: last completed 1h candle close vs its 20 EMA
    htf = hist.htf(60)
    if len(htf.close) < 1:
        return {"target": pos, "stop": None, "take": None}
    htf_close = htf.close[-1]
    htf_ema20 = ind.ema(htf.close, 20)
    if len(htf_ema20) < 1 or np.isnan(htf_ema20[-1]):
        return {"target": pos, "stop": None, "take": None}
    htf_ema20_val = htf_ema20[-1]
    trend_long = htf_close > htf_ema20_val
    trend_short = htf_close < htf_ema20_val

    # Daily entry cap (2 new entries per UTC day)
    current_time = hist.time[-1]
    day_start = (current_time // 86400000) * 86400000
    last_day = state.get('last_day_ts', 0)
    if day_start != last_day:
        state['day_entries'] = 0
        state['last_day_ts'] = day_start
    day_entries = state.get('day_entries', 0)

    # Trade state
    in_trade = pos != 0.0
    trade_dir = state.get('trade_dir', 0)

    # Clear stale trade state when flat
    if not in_trade and trade_dir != 0:
        for key in ('trade_dir', 'entry_price', 'entry_atr', 'n_ratchets', 'extreme'):
            if key in state:
                del state[key]
        trade_dir = 0

    if in_trade:
        # Safety: if state doesn't match position, reset
        if (pos > 0 and trade_dir != 1) or (pos < 0 and trade_dir != -1):
            for key in ('trade_dir', 'entry_price', 'entry_atr', 'n_ratchets', 'extreme'):
                if key in state:
                    del state[key]
            return {"target": pos, "stop": None, "take": None}

        # Update extreme price
        if trade_dir == 1:
            extreme = max(state['extreme'], hist.high[-1])
        else:
            extreme = min(state['extreme'], hist.low[-1])
        state['extreme'] = extreme

        entry_price = state['entry_price']
        entry_atr = state['entry_atr']
        n = state['n_ratchets']
        close_curr = hist.close[-1]

        # Ratchet the box when close clears another 2 ATR in our favour
        if trade_dir == 1:
            while close_curr >= entry_price + 2 * (n + 1) * entry_atr:
                n += 1
        else:
            while close_curr <= entry_price - 2 * (n + 1) * entry_atr:
                n += 1
        state['n_ratchets'] = n

        # Box stop and take
        if trade_dir == 1:
            box_stop = entry_price + (2 * n - 1) * entry_atr
            box_take = entry_price + (2 * n + 2) * entry_atr
            trail_stop = extreme - 4 * entry_atr
            stop = max(box_stop, trail_stop)          # tightest stop for long
        else:
            box_stop = entry_price - (2 * n - 1) * entry_atr
            box_take = entry_price - (2 * n + 2) * entry_atr
            trail_stop = extreme + 4 * entry_atr
            stop = min(box_stop, trail_stop)          # tightest stop for short

        # Opposite signal closes the trade at next open
        opposite = False
        if trade_dir == 1 and cross_down and trend_short:
            opposite = True
        elif trade_dir == -1 and cross_up and trend_long:
            opposite = True

        if opposite:
            for key in ('trade_dir', 'entry_price', 'entry_atr', 'n_ratchets', 'extreme'):
                if key in state:
                    del state[key]
            return {"target": 0.0, "stop": None, "take": None}

        return {"target": pos, "stop": stop, "take": box_take}

    else:
        # Flat – look for new entries
        if cross_up and trend_long:
            if day_entries < 2:
                entry_price = hist.close[-1]
                entry_atr = ind.atr(hist, 14)[-1]
                if np.isnan(entry_atr):
                    return {"target": pos, "stop": None, "take": None}
                state['trade_dir'] = 1
                state['entry_price'] = entry_price
                state['entry_atr'] = entry_atr
                state['n_ratchets'] = 0
                state['extreme'] = entry_price          # extreme starts at entry
                state['day_entries'] = day_entries + 1

                box_stop = entry_price - entry_atr
                box_take = entry_price + 2 * entry_atr
                trail_stop = entry_price - 4 * entry_atr
                stop = max(box_stop, trail_stop)
                return {"target": 0.75, "stop": stop, "take": box_take}

        elif cross_down and trend_short:
            if day_entries < 2:
                entry_price = hist.close[-1]
                entry_atr = ind.atr(hist, 14)[-1]
                if np.isnan(entry_atr):
                    return {"target": pos, "stop": None, "take": None}
                state['trade_dir'] = -1
                state['entry_price'] = entry_price
                state['entry_atr'] = entry_atr
                state['n_ratchets'] = 0
                state['extreme'] = entry_price
                state['day_entries'] = day_entries + 1

                box_stop = entry_price + entry_atr
                box_take = entry_price - 2 * entry_atr
                trail_stop = entry_price + 4 * entry_atr
                stop = min(box_stop, trail_stop)
                return {"target": -0.75, "stop": stop, "take": box_take}

        return {"target": pos, "stop": None, "take": None}

import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Compute 21-period RSI
    rsi = ind.rsi(hist.close, 21)
    if np.isnan(rsi[-1]) or np.isnan(rsi[-2]):
        return {"target": pos, "stop": None, "take": None}

    # Signal definitions: cross events
    long_signal = (rsi[-2] <= 25 and rsi[-1] > 25)
    short_signal = (rsi[-2] >= 75 and rsi[-1] < 75)

    # Helper to round target to 0.05 grid
    def grid_round(x):
        return round(x * 20) / 20.0

    if pos == 0.0:
        # Clear any stale trade state
        for k in ('entry_price', 'entry_atr', 'add_count', 'last_add_price', 'ratchet_count'):
            state.pop(k, None)

        if long_signal:
            entry_price = hist.close[-1]
            entry_atr = ind.atr(hist, 14)[-1]
            if np.isnan(entry_atr):
                return {"target": pos, "stop": None, "take": None}
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['add_count'] = 0
            state['last_add_price'] = entry_price
            state['ratchet_count'] = 0
            target = grid_round(0.5)
            stop = entry_price - 2 * entry_atr
            take = entry_price + 3 * entry_atr
            return {"target": target, "stop": stop, "take": take}

        if short_signal:
            entry_price = hist.close[-1]
            entry_atr = ind.atr(hist, 14)[-1]
            if np.isnan(entry_atr):
                return {"target": pos, "stop": None, "take": None}
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['add_count'] = 0
            state['last_add_price'] = entry_price
            state['ratchet_count'] = 0
            target = grid_round(-0.5)
            stop = entry_price + 2 * entry_atr
            take = entry_price - 3 * entry_atr
            return {"target": target, "stop": stop, "take": take}

        return {"target": pos, "stop": None, "take": None}

    # We have an open position
    # Opposite signal closes the trade
    if (pos > 0 and short_signal) or (pos < 0 and long_signal):
        for k in ('entry_price', 'entry_atr', 'add_count', 'last_add_price', 'ratchet_count'):
            state.pop(k, None)
        return {"target": 0.0, "stop": None, "take": None}

    # Retrieve trade state
    entry_price = state.get('entry_price')
    entry_atr = state.get('entry_atr')
    if entry_price is None or entry_atr is None:
        return {"target": pos, "stop": None, "take": None}

    add_count = state.get('add_count', 0)
    last_add_price = state.get('last_add_price', entry_price)
    ratchet_count = state.get('ratchet_count', 0)

    direction = 1 if pos > 0 else -1
    target = pos  # default: no change

    # Pyramiding: add up to two times, 50% each, cap at 100%
    if add_count < 2 and abs(pos) < 1.0:
        if direction == 1:
            if hist.close[-1] >= last_add_price + 2 * entry_atr:
                add_count += 1
                last_add_price = hist.close[-1]
                target = min(1.0, 0.5 * (add_count + 1))
        else:  # short
            if hist.close[-1] <= last_add_price - 2 * entry_atr:
                add_count += 1
                last_add_price = hist.close[-1]
                target = -min(1.0, 0.5 * (add_count + 1))

        if add_count != state.get('add_count', 0):
            state['add_count'] = add_count
            state['last_add_price'] = last_add_price

    # Trailing box ratchet
    if direction == 1:
        while hist.close[-1] >= entry_price + 2 * entry_atr * (ratchet_count + 1):
            ratchet_count += 1
    else:
        while hist.close[-1] <= entry_price - 2 * entry_atr * (ratchet_count + 1):
            ratchet_count += 1
    state['ratchet_count'] = ratchet_count

    # Compute stop and take levels
    if direction == 1:
        stop = entry_price - 2 * entry_atr + 2 * entry_atr * ratchet_count
        take = entry_price + 3 * entry_atr + 2 * entry_atr * ratchet_count
    else:
        stop = entry_price + 2 * entry_atr - 2 * entry_atr * ratchet_count
        take = entry_price - 3 * entry_atr - 2 * entry_atr * ratchet_count

    return {"target": grid_round(target), "stop": stop, "take": take}

import numpy as np

# Constants
RSI_PERIOD = 7
RSI_OVERSOLD = 25
RSI_OVERBOUGHT = 75
ATR_PERIOD = 14
PROFIT_ATR_MULT = 2
COOLDOWN_BARS = 16
MS_PER_DAY = 24 * 3600 * 1000


def strategy(hist, state, pos, ind) -> dict:
    """
    Long-only oversold bounce strategy.
    - Entry: RSI(7) crosses back up through 25, flat, cooldown expired, max 1 trade/day.
    - Target: 1.0 (full equity).
    - Partial profit: when close >= entry_price + 2 * entry_ATR, reduce to 0.5.
    - Exit: after partial profit, RSI(7) crosses down through 75 -> target 0.
    - Cooldown: 16 bars after becoming flat.
    """
    t = len(hist) - 1
    current_close = hist.close[-1]
    current_day = hist.time[-1] // MS_PER_DAY

    # Initialize state with defaults
    if 'cooldown_until' not in state:
        state['cooldown_until'] = -1
    if 'last_entry_day' not in state:
        state['last_entry_day'] = -1
    if 'partial_taken' not in state:
        state['partial_taken'] = False
    if 'entry_price' not in state:
        state['entry_price'] = 0.0
    if 'entry_atr' not in state:
        state['entry_atr'] = 0.0

    # Flat: look for entry
    if pos == 0.0:
        # Check cooldown and daily trade limit
        if t > state['cooldown_until'] and current_day != state['last_entry_day']:
            rsi7 = ind.rsi(hist.close, RSI_PERIOD)
            if len(rsi7) >= 2:
                rsi_prev = rsi7[-2]
                rsi_curr = rsi7[-1]
                # RSI crosses up through 25
                if rsi_prev <= RSI_OVERSOLD and rsi_curr > RSI_OVERSOLD:
                    # Enter long
                    state['entry_price'] = current_close
                    state['entry_atr'] = ind.atr(hist, ATR_PERIOD)[-1]
                    state['partial_taken'] = False
                    state['last_entry_day'] = current_day
                    return {"target": 1.0, "stop": None, "take": None}
        # No entry
        return {"target": 0.0, "stop": None, "take": None}

    # In a long trade
    if pos > 0.0:
        # Full position, not yet taken partial profit
        if not state['partial_taken']:
            # Check partial profit condition
            if current_close >= state['entry_price'] + PROFIT_ATR_MULT * state['entry_atr']:
                state['partial_taken'] = True
                return {"target": 0.5, "stop": None, "take": None}
            else:
                return {"target": 1.0, "stop": None, "take": None}

        # Partial profit already taken, manage runner
        else:
            rsi7 = ind.rsi(hist.close, RSI_PERIOD)
            if len(rsi7) >= 2:
                rsi_prev = rsi7[-2]
                rsi_curr = rsi7[-1]
                # RSI crosses down through 75 -> exit runner
                if rsi_prev >= RSI_OVERBOUGHT and rsi_curr < RSI_OVERBOUGHT:
                    state['cooldown_until'] = t + COOLDOWN_BARS
                    # Reset trade-specific state (optional but clean)
                    state['partial_taken'] = False
                    return {"target": 0.0, "stop": None, "take": None}
            # Hold runner
            return {"target": 0.5, "stop": None, "take": None}

    # Fallback (should never reach here)
    return {"target": pos, "stop": None, "take": None}

