    rsi = ind.rsi(hist.close, 14)

    # Need at least two RSI values for a cross
    if len(rsi) < 2 or np.isnan(rsi[-2]) or np.isnan(rsi[-1]):
        return {"target": pos, "stop": None, "take": None}

    rsi_prev = rsi[-2]
    rsi_curr = rsi[-1]

    long_signal = (rsi_prev <= 30 and rsi_curr > 30)
    short_signal = (rsi_prev >= 70 and rsi_curr < 70)

    in_trade = state.get("in_trade", False)

    # If we think we are in a trade but the position is flat, the trade was closed
    # by a stop/take fill or a previous close signal. Clear state.
    if in_trade and pos == 0.0:
        for key in list(state.keys()):
            del state[key]
        in_trade = False

    if in_trade:
        direction = state["direction"]

        # Opposite signal closes the trade at the next open
        if (direction == 1 and short_signal) or (direction == -1 and long_signal):
            for key in list(state.keys()):
                del state[key]
            return {"target": 0.0, "stop": None, "take": None}

        entry_price = state["entry_price"]
        entry_atr = state["entry_atr"]
        breakeven_activated = state.get("breakeven_activated", False)

        # Check profit condition to activate breakeven stop
        if not breakeven_activated:
            if direction == 1:
                if close >= entry_price + 1.5 * entry_atr:
                    breakeven_activated = True
                    state["breakeven_activated"] = True
            else:  # short
                if close <= entry_price - 1.5 * entry_atr:
                    breakeven_activated = True
                    state["breakeven_activated"] = True

        # Set take profit and stop
        if direction == 1:
            take = entry_price + 6 * entry_atr
            stop = entry_price if breakeven_activated else None
        else:
            take = entry_price - 6 * entry_atr
            stop = entry_price if breakeven_activated else None

        return {"target": pos, "stop": stop, "take": take}

    # Flat
    if pos != 0.0:
        # Safety: if state is inconsistent, clear it
        if in_trade:
            for key in list(state.keys()):
                del state[key]
        return {"target": pos, "stop": None, "take": None}

    if long_signal:
        fraction = 0.01 * close / atr_val
        fraction = max(0.05, min(1.0, fraction))
        target = round(fraction / 0.05) * 0.05
        target = max(0.05, min(1.0, target))

        state["in_trade"] = True
        state["direction"] = 1
        state["entry_price"] = close
        state["entry_atr"] = atr_val
        state["breakeven_activated"] = False

        take = close + 6 * atr_val
        return {"target": target, "stop": None, "take": take}

    if short_signal:
        fraction = 0.01 * close / atr_val
        fraction = max(0.05, min(1.0, fraction))
        target = round(fraction / 0.05) * 0.05
        target = max(0.05, min(1.0, target))

        state["in_trade"] = True
        state["direction"] = -1
        state["entry_price"] = close
        state["entry_atr"] = atr_val
        state["breakeven_activated"] = False

        take = close - 6 * atr_val
        return {"target": -target, "stop": None, "take": take}

    # No signal
    return {"target": 0.0, "stop": None, "take": None}

