def strategy(hist, state, pos, ind):
    # Prior 96-bar Donchian levels (highest high / lowest low of the 96 bars before the current bar)
    highest96 = ind.highest(hist.high, 96)
    lowest96 = ind.lowest(hist.low, 96)
    donchian_high = highest96[-2]
    donchian_low = lowest96[-2]

    # 4-hour trend filter: close vs 20 EMA on completed 4h candles
    htf = hist.htf(240)
    ema20_4h = ind.ema(htf.close, 20)
    htf_close = htf.close[-1]
    htf_ema = ema20_4h[-1]

    long_signal = hist.close[-1] > donchian_high and htf_close > htf_ema
    short_signal = hist.close[-1] < donchian_low and htf_close < htf_ema

    if pos == 0:
        # Clear any leftover trade state
        for k in ('entry_price', 'entry_atr', 'dir', 'scaled'):
            if k in state:
                del state[k]

        if long_signal:
            state['entry_price'] = float(hist.close[-1])
            state['entry_atr'] = float(ind.atr(hist, 14)[-1])
            state['dir'] = 1
            state['scaled'] = False
            return {"target": 1.0, "stop": None, "take": None}
        elif short_signal:
            state['entry_price'] = float(hist.close[-1])
            state['entry_atr'] = float(ind.atr(hist, 14)[-1])
            state['dir'] = -1
            state['scaled'] = False
            return {"target": -1.0, "stop": None, "take": None}
        else:
            return {"target": 0.0, "stop": None, "take": None}

    # We have an open position
    entry_price = state['entry_price']
    entry_atr = state['entry_atr']
    direction = state['dir']
    scaled = state['scaled']

    # Opposite Donchian signal closes the trade (desk convention: no reversal)
    if direction == 1 and short_signal:
        for k in ('entry_price', 'entry_atr', 'dir', 'scaled'):
            if k in state: del state[k]
        return {"target": 0.0, "stop": None, "take": None}
    if direction == -1 and long_signal:
        for k in ('entry_price', 'entry_atr', 'dir', 'scaled'):
            if k in state: del state[k]
        return {"target": 0.0, "stop": None, "take": None}

    # Scale-out logic: once 2 ATR in profit, ratchet stop to breakeven and halve the position
    if not scaled:
        if direction == 1:
            if hist.close[-1] >= entry_price + 2 * entry_atr:
                state['scaled'] = True
                return {"target": 0.5, "stop": entry_price, "take": None}
        else:  # direction == -1
            if hist.close[-1] <= entry_price - 2 * entry_atr:
                state['scaled'] = True
                return {"target": -0.5, "stop": entry_price, "take": None}
        # No scale-out yet – keep full size, no stop/take
        return {"target": 1.0 if direction == 1 else -1.0, "stop": None, "take": None}
    else:
        # Already scaled – maintain half size with breakeven stop
        return {"target": 0.5 if direction == 1 else -0.5, "stop": entry_price, "take": None}

