    atr = ind.atr(hist, 14)[-1]

    # Need at least 65 bars to compute prior 64-bar box
    if len(hist) < 65:
        return {"target": pos, "stop": None, "take": None}

    # Prior 64 bars (indices -65 to -2)
    prior_high = max(hist.high[-65:-1])
    prior_low = min(hist.low[-65:-1])
    box_height = prior_high - prior_low

    # Box is valid only if height <= 6 ATR
    box_valid = box_height <= 6 * atr

    # Breakout signals (level conditions, checked every bar)
    long_signal = False
    short_signal = False
    if box_valid:
        if close > prior_high:
            long_signal = True
        elif close < prior_low:
            short_signal = True

    # ------------------------------------------------------------------
    # In a trade
    # ------------------------------------------------------------------
    if pos != 0.0:
        # Opposite signal -> bail at next open
        if (pos > 0 and short_signal) or (pos < 0 and long_signal):
            for key in ('entry_price', 'entry_atr', 'direction', 'ratchet_done'):
                state.pop(key, None)
            return {"target": 0.0, "stop": None, "take": None}

        # Retrieve trade parameters
        entry_price = state.get('entry_price')
        entry_atr = state.get('entry_atr')
        direction = state.get('direction')
        ratchet_done = state.get('ratchet_done', False)

        # If state is missing (should not happen), just hold
        if entry_price is None:
            return {"target": pos, "stop": None, "take": None}

        # Check ratchet condition: 2 ATR in profit (inclusive)
        if not ratchet_done:
            if direction == 1:
                if close >= entry_price + 2 * entry_atr:
                    ratchet_done = True
                    state['ratchet_done'] = True
            else:  # direction == -1
                if close <= entry_price - 2 * entry_atr:
                    ratchet_done = True
                    state['ratchet_done'] = True

        # Set stop and take
        stop = entry_price if ratchet_done else None
        take = entry_price + direction * 3 * entry_atr

        return {"target": pos, "stop": stop, "take": take}

    # ------------------------------------------------------------------
    # Flat – look for entry
    # ------------------------------------------------------------------
    if pos == 0.0:
        if long_signal:
            state['entry_price'] = close
            state['entry_atr'] = atr
            state['direction'] = 1
            state['ratchet_done'] = False
            return {"target": 1.0, "stop": None, "take": close + 3 * atr}

        if short_signal:
            state['entry_price'] = close
            state['entry_atr'] = atr
            state['direction'] = -1
            state['ratchet_done'] = False
            return {"target": -1.0, "stop": None, "take": close - 3 * atr}

