    return {"target": pos, "stop": None, "take": None}

import math
import numpy as np


def compute_target(close, atr):
    """Return positive target fraction before rounding and capping."""
    raw = 0.01 * close / atr          # risk 1% per 1 ATR
    target = min(raw, 1.0)            # cap at 1.0
    target = max(target, 0.05)        # floor at 0.05
    return target


def strategy(hist, state, pos, ind):
    close = hist.close[-1]
    atr = ind.atr(hist, 14)[-1]
    if np.isnan(atr):
        return {"target": pos, "stop": None, "take": None}

    # 32-bar box (prior 32 bars, not including current)
    box_high = ind.highest(hist.high, 32)[-2]
    box_low = ind.lowest(hist.low, 32)[-2]
    if np.isnan(box_high) or np.isnan(box_low):
        return {"target": pos, "stop": None, "take": None}

    box_height = box_high - box_low
    signal = 0
    if box_height <= 4 * atr:
        if close > box_high:
            signal = 1
        elif close < box_low:
            signal = -1

    current_day = hist.time[-1] // 86400000   # UTC day

    # ----- FLAT -----
    if pos == 0.0:
        if signal != 0:
            last_day = state.get("last_entry_day", -1)
            if current_day != last_day:       # max 1 trade per day
                frac = compute_target(close, atr)
                target = frac * signal
                target = round(target / 0.05) * 0.05
                if target > 1.0:
                    target = 1.0
                elif target < -1.0:
                    target = -1.0

                state["entry_price"] = close
                state["entry_atr"] = atr
                state["last_entry_day"] = current_day
                take = close + signal * 6 * atr
                return {"target": target, "stop": None, "take": take}
        return {"target": 0.0, "stop": None, "take": None}

    # ----- IN A TRADE -----
    direction = 1 if pos > 0 else -1
    opposite_signal = 0
    if signal == -direction:
        opposite_signal = signal

    if opposite_signal != 0:          # flip at next open
        frac = compute_target(close, atr)
        target = frac * opposite_signal
        target = round(target / 0.05) * 0.05
        if target > 1.0:
            target = 1.0
        elif target < -1.0:
            target = -1.0

        state["entry_price"] = close
        state["entry_atr"] = atr
        # do NOT update last_entry_day – flip does not count as a new daily trade
        take = close + opposite_signal * 6 * atr
        return {"target": target, "stop": None, "take": take}
    else:
        entry_price = state["entry_price"]
        entry_atr = state["entry_atr"]
        take = entry_price + direction * 6 * entry_atr
        return {"target": pos, "stop": None, "take": take}

