import math
import numpy as np

# Constants
RISK = 0.0025          # 0.25% risk per 1 ATR
ATR_PERIOD = 14
BOX_LENGTH = 32
BOX_ATR_MULT = 4       # max box height in ATR
TP_ATR_MULT = 4        # take-profit distance in ATR
PARTIAL_ATR_MULT = 2   # partial profit trigger in ATR
GRID = 0.05
CAP = 1.0
FLOOR = 0.05

def round_to_grid(x: float) -> float:
    """Round x to the nearest 0.05 grid."""
    return round(x / GRID) * GRID

def strategy(hist, state, pos, ind) -> dict:
    # If flat, clear any stale trade state
    if pos == 0.0:
        for k in ['entry_price', 'entry_atr', 'direction', 'partial_taken']:
            state.pop(k, None)

        # Need at least 33 bars to form a 32-bar box (prior 32 bars)
        if len(hist) < 33:
            return {'target': pos, 'stop': None, 'take': None}

        # Box from prior 32 bars (indices -33 to -2)
        hh = np.max(hist.high[-33:-1])
        ll = np.min(hist.low[-33:-1])
        atr = ind.atr(hist, ATR_PERIOD)[-1]
        if np.isnan(atr):
            return {'target': pos, 'stop': None, 'take': None}

        box_height = hh - ll
        if box_height <= BOX_ATR_MULT * atr:
            close = hist.close[-1]
            if close > hh:   # long breakout
                size = RISK * close / atr
                size = min(max(size, FLOOR), CAP)
                target = round_to_grid(size)
                state['entry_price'] = float(close)
                state['entry_atr'] = float(atr)
                state['direction'] = 1
                state['partial_taken'] = False
                take = close + TP_ATR_MULT * atr
                return {'target': target, 'stop': None, 'take': take}
            elif close < ll: # short breakout
                size = RISK * close / atr
                size = min(max(size, FLOOR), CAP)
                target = -round_to_grid(size)
                state['entry_price'] = float(close)
                state['entry_atr'] = float(atr)
                state['direction'] = -1
                state['partial_taken'] = False
                take = close - TP_ATR_MULT * atr
                return {'target': target, 'stop': None, 'take': take}

        # No valid signal
        return {'target': pos, 'stop': None, 'take': None}

    # We are in a trade
    entry_price = state.get('entry_price')
    entry_atr = state.get('entry_atr')
    direction = state.get('direction')
    partial_taken = state.get('partial_taken', False)

    if entry_price is None or entry_atr is None or direction is None:
        # Should not happen, but safety
        return {'target': pos, 'stop': None, 'take': None}

    # Compute current box for opposite signal
    if len(hist) < 33:
        take = entry_price + direction * TP_ATR_MULT * entry_atr
        return {'target': pos, 'stop': None, 'take': take}

    hh = np.max(hist.high[-33:-1])
    ll = np.min(hist.low[-33:-1])
    atr = ind.atr(hist, ATR_PERIOD)[-1]
    if np.isnan(atr):
        take = entry_price + direction * TP_ATR_MULT * entry_atr
        return {'target': pos, 'stop': None, 'take': take}

    box_height = hh - ll
    close = hist.close[-1]

    # Opposite signal closes the whole position (takes precedence)
    if box_height <= BOX_ATR_MULT * atr:
        if direction == 1 and close < ll:
            for k in ['entry_price', 'entry_atr', 'direction', 'partial_taken']:
                state.pop(k, None)
            return {'target': 0.0, 'stop': None, 'take': None}
        if direction == -1 and close > hh:
            for k in ['entry_price', 'entry_atr', 'direction', 'partial_taken']:
                state.pop(k, None)
            return {'target': 0.0, 'stop': None, 'take': None}

    # Partial profit taking (first time only)
    if not partial_taken:
        if direction == 1 and close >= entry_price + PARTIAL_ATR_MULT * entry_atr:
            new_target = round_to_grid(pos / 2.0)
            state['partial_taken'] = True
            take = entry_price + direction * TP_ATR_MULT * entry_atr
            return {'target': new_target, 'stop': None, 'take': take}
        if direction == -1 and close <= entry_price - PARTIAL_ATR_MULT * entry_atr:
            new_target = round_to_grid(pos / 2.0)
            state['partial_taken'] = True
            take = entry_price + direction * TP_ATR_MULT * entry_atr
            return {'target': new_target, 'stop': None, 'take': take}

    # Maintain position with hard take-profit
    take = entry_price + direction * TP_ATR_MULT * entry_atr
    return {'target': pos, 'stop': None, 'take': take}

