def strategy(hist, state, pos, ind):
    """
    Mean reversion strategy using RSI(14) crossovers on 15-minute bars.

    Long:  RSI crosses back up through 30 (prev <= 30, curr > 30)
    Short: RSI crosses back down through 70 (prev >= 70, curr < 70)

    Entries only when flat, respecting a 48-bar cooldown after any trade ends
    and a maximum of 2 new entries per UTC calendar day.
    Opposite signal closes the open trade (target 0) without reversing.
    Position sizing: risk 1% of equity per 2 ATR, capped at 1.0, floored at 0.05,
    rounded to the 0.05 grid.
    """
    t = len(hist) - 1  # current bar index

    # --- retrieve persistent state -------------------------------------------
    prev_pos = state.get('prev_pos', 0.0)
    cooldown_until = state.get('cooldown_until', -1)
    entry_day = state.get('entry_day', -1)
    entries_today = state.get('entries_today', 0)

    # --- detect trade end and set cooldown -----------------------------------
    if prev_pos != 0.0 and pos == 0.0:
        cooldown_until = t + 48
        state['cooldown_until'] = cooldown_until

    # store current position for the next call
    state['prev_pos'] = pos

    # --- if we are in a trade, check for an opposite signal to close ---------
    if pos != 0.0:
        rsi = ind.rsi(hist.close, 14)
        if len(rsi) < 2:
            return {"target": pos, "stop": None, "take": None}

        rsi_prev = rsi[-2]
        rsi_curr = rsi[-1]

        if pos > 0:
            # long position: short signal (cross down through 70) closes it
            if rsi_prev >= 70 and rsi_curr < 70:
                return {"target": 0.0, "stop": None, "take": None}
        else:  # pos < 0
            # short position: long signal (cross up through 30) closes it
            if rsi_prev <= 30 and rsi_curr > 30:
                return {"target": 0.0, "stop": None, "take": None}

        # no opposite signal – maintain position
        return {"target": pos, "stop": None, "take": None}

    # --- we are flat ---------------------------------------------------------
    # cooldown check
    if t <= cooldown_until:
        return {"target": 0.0, "stop": None, "take": None}

    # daily entry limit
    current_day = hist.time[-1] // (24 * 3600 * 1000)  # UTC day number
    if current_day != entry_day:
        entry_day = current_day
        entries_today = 0
        state['entry_day'] = entry_day
        state['entries_today'] = entries_today

    if entries_today >= 2:
        return {"target": 0.0, "stop": None, "take": None}

    # --- compute entry signals -----------------------------------------------
    rsi = ind.rsi(hist.close, 14)
    if len(rsi) < 2:
        return {"target": 0.0, "stop": None, "take": None}

    rsi_prev = rsi[-2]
    rsi_curr = rsi[-1]

    long_signal = (rsi_prev <= 30 and rsi_curr > 30)
    short_signal = (rsi_prev >= 70 and rsi_curr < 70)

    if long_signal:
        atr = ind.atr(hist, 14)[-1]
        close = hist.close[-1]
        if atr <= 0:
            return {"target": 0.0, "stop": None, "take": None}
        fraction = 0.01 * close / (2 * atr)
        fraction = max(0.05, min(1.0, fraction))
        target = round_to_grid(fraction)

        entries_today += 1
        state['entries_today'] = entries_today
        return {"target": target, "stop": None, "take": None}

    if short_signal:
        atr = ind.atr(hist, 14)[-1]
        close = hist.close[-1]
        if atr <= 0:
            return {"target": 0.0, "stop": None, "take": None}
        fraction = 0.01 * close / (2 * atr)
        fraction = max(0.05, min(1.0, fraction))
        target = -round_to_grid(fraction)

        entries_today += 1
        state['entries_today'] = entries_today
        return {"target": target, "stop": None, "take": None}

    # no signal
    return {"target": 0.0, "stop": None, "take": None}

import math
import numpy as np

# Constants
ATR_PERIOD = 14
DONCHIAN_PERIOD = 96
RISK = 0.01          # 1%
ATR_MULT = 1         # risk per 1 ATR
CAP = 1.0
FLOOR = 0.05
PROFIT_ATR_MULT = 2  # scale-out at 2 ATR profit
GRID = 0.05

def round_to_grid(x: float) -> float:
    """Round x to the nearest 0.05."""
    return round(x / GRID) * GRID

def clamp(x: float, low: float, high: float) -> float:
    return max(low, min(high, x))

def strategy(hist, state, pos, ind) -> dict:
    # Current bar close and ATR
    close = hist.close[-1]
    atr_val = ind.atr(hist, ATR_PERIOD)[-1]

    # Prior 96-bar high and low (the 96 bars BEFORE the current bar)
    # ind.highest(hist.high, 96)[-2] gives the highest of the 96 bars ending at the previous bar.
    prior_high = ind.highest(hist.high, DONCHIAN_PERIOD)[-2]
    prior_low = ind.lowest(hist.low, DONCHIAN_PERIOD)[-2]

    long_signal = close > prior_high
    short_signal = close < prior_low

    # Flat
    if pos == 0.0:
        if long_signal:
            size = clamp(RISK * close / (ATR_MULT * atr_val), FLOOR, CAP)
            target = round_to_grid(size)
            state['entry_price'] = close
            state['entry_ATR'] = atr_val
            state['scaled_out'] = False
            return {"target": target, "stop": None, "take": None}
        elif short_signal:
            size = clamp(RISK * close / (ATR_MULT * atr_val), FLOOR, CAP)
            target = -round_to_grid(size)
            state['entry_price'] = close
            state['entry_ATR'] = atr_val
            state['scaled_out'] = False
            return {"target": target, "stop": None, "take": None}
        else:
            return {"target": 0.0, "stop": None, "take": None}

    # Long position
    if pos > 0.0:
        # Scale-out logic (only once)
        if not state.get('scaled_out', False):
            entry_price = state['entry_price']
            entry_ATR = state['entry_ATR']
            if close >= entry_price + PROFIT_ATR_MULT * entry_ATR:
                new_target = round_to_grid(pos / 2.0)
                state['scaled_out'] = True
                return {"target": new_target, "stop": None, "take": None}

        # Opposite signal -> flip to short
        if short_signal:
            size = clamp(RISK * close / (ATR_MULT * atr_val), FLOOR, CAP)
            target = -round_to_grid(size)
            state['entry_price'] = close
            state['entry_ATR'] = atr_val
            state['scaled_out'] = False
            return {"target": target, "stop": None, "take": None}

        # Maintain position
        return {"target": pos, "stop": None, "take": None}

    # Short position (pos < 0)
    if not state.get('scaled_out', False):
        entry_price = state['entry_price']
        entry_ATR = state['entry_ATR']
        if close <= entry_price - PROFIT_ATR_MULT * entry_ATR:
            new_target = round_to_grid(pos / 2.0)  # pos is negative, division keeps sign
            state['scaled_out'] = True
            return {"target": new_target, "stop": None, "take": None}

    if long_signal:
        size = clamp(RISK * close / (ATR_MULT * atr_val), FLOOR, CAP)
        target = round_to_grid(size)
        state['entry_price'] = close
        state['entry_ATR'] = atr_val
        state['scaled_out'] = False
        return {"target": target, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

import math
import numpy as np

RSI_PERIOD = 21
RSI_OVERSOLD = 25
RSI_OVERBOUGHT = 75
ATR_PERIOD = 14
TP_ATR_MULT = 4.0
BE_ATR_MULT = 0.5

def strategy(hist, state, pos, ind) -> dict:
    # If flat, clear any leftover trade state (e.g. after a stop/take fill)
    if pos == 0.0:
        if 'entry_price' in state:
            for key in ('entry_price', 'entry_atr', 'direction', 'breakeven_triggered'):
                state.pop(key, None)

    # Compute indicators
    rsi = ind.rsi(hist.close, RSI_PERIOD)
    atr = ind.atr(hist, ATR_PERIOD)

    # Need at least two RSI values for a cross
    if len(rsi) < 2:
        return {"target": pos, "stop": None, "take": None}

    rsi_curr = rsi[-1]
    rsi_prev = rsi[-2]
    if np.isnan(rsi_curr) or np.isnan(rsi_prev):
        return {"target": pos, "stop": None, "take": None}

    # Signal definitions
    long_signal = (rsi_prev < RSI_OVERSOLD) and (rsi_curr >= RSI_OVERSOLD)
    short_signal = (rsi_prev > RSI_OVERBOUGHT) and (rsi_curr <= RSI_OVERBOUGHT)

    # --- FLAT ---
    if pos == 0.0:
        if long_signal:
            entry_price = hist.close[-1]
            entry_atr = atr[-1]
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['direction'] = 1
            state['breakeven_triggered'] = False
            take = entry_price + TP_ATR_MULT * entry_atr
            return {"target": 1.0, "stop": None, "take": take}

        if short_signal:
            entry_price = hist.close[-1]
            entry_atr = atr[-1]
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['direction'] = -1
            state['breakeven_triggered'] = False
            take = entry_price - TP_ATR_MULT * entry_atr
            return {"target": -1.0, "stop": None, "take": take}

        # No signal
        return {"target": 0.0, "stop": None, "take": None}

    # --- IN A TRADE ---
    direction = state.get('direction', 0)
    if direction == 0:          # state missing – safety fallback
        return {"target": pos, "stop": None, "take": None}

    # Opposite signal closes the trade immediately
    if direction == 1 and short_signal:
        for key in ('entry_price', 'entry_atr', 'direction', 'breakeven_triggered'):
            state.pop(key, None)
        return {"target": 0.0, "stop": None, "take": None}
    if direction == -1 and long_signal:
        for key in ('entry_price', 'entry_atr', 'direction', 'breakeven_triggered'):
            state.pop(key, None)
        return {"target": 0.0, "stop": None, "take": None}

    # Manage existing trade
    entry_price = state['entry_price']
    entry_atr = state['entry_atr']
    breakeven_triggered = state['breakeven_triggered']

    # Check breakeven condition (once per trade)
    if not breakeven_triggered:
        if direction == 1:
            if hist.close[-1] >= entry_price + BE_ATR_MULT * entry_atr:
                breakeven_triggered = True
                state['breakeven_triggered'] = True
        else:  # direction == -1
            if hist.close[-1] <= entry_price - BE_ATR_MULT * entry_atr:
                breakeven_triggered = True
                state['breakeven_triggered'] = True

    # Set stop and take
    stop = entry_price if breakeven_triggered else None
    if direction == 1:
        take = entry_price + TP_ATR_MULT * entry_atr
    else:
        take = entry_price - TP_ATR_MULT * entry_atr

    # Maintain current position
    return {"target": pos, "stop": stop, "take": take}

import math
import numpy as np

def strategy(hist, state, pos, ind):
    # If flat, clear any stale state
    if pos == 0:
        for k in list(state.keys()):
            del state[k]

    close = hist.close[-1]
    atr = ind.atr(hist, 14)
    curr_atr = atr[-1]
    rsi = ind.rsi(hist.close, 21)

    # Need at least two RSI values to detect a cross
    if len(rsi) < 2:
        return {"target": pos, "stop": None, "take": None}
    curr_rsi = rsi[-1]
    prev_rsi = rsi[-2]
    if np.isnan(curr_rsi) or np.isnan(prev_rsi):
        return {"target": pos, "stop": None, "take": None}

    # Cross signals
    long_signal = (prev_rsi <= 30 and curr_rsi > 30)
    short_signal = (prev_rsi >= 70 and curr_rsi < 70)

    # --- FLAT ---
    if pos == 0:
        if long_signal:
            raw = (0.0025 * close) / (1.0 * curr_atr)
            abs_target = min(max(raw, 0.05), 1.0)
            rounded = round(abs_target * 20) / 20
            state["entry_price"] = close
            state["entry_atr"] = curr_atr
            state["direction"] = 1.0
            state["breakeven"] = False
            return {"target": rounded, "stop": None, "take": None}
        elif short_signal:
            raw = (0.0025 * close) / (1.0 * curr_atr)
            abs_target = min(max(raw, 0.05), 1.0)
            rounded = round(abs_target * 20) / 20
            state["entry_price"] = close
            state["entry_atr"] = curr_atr
            state["direction"] = -1.0
            state["breakeven"] = False
            return {"target": -rounded, "stop": None, "take": None}
        else:
            return {"target": 0.0, "stop": None, "take": None}

    # --- IN A TRADE ---
    if "direction" not in state:
        # Safety: if state was lost, just hold
        return {"target": pos, "stop": None, "take": None}

    direction = state["direction"]

    # Opposite signal -> flatten
    if (direction == 1.0 and short_signal) or (direction == -1.0 and long_signal):
        for k in list(state.keys()):
            del state[k]
        return {"target": 0.0, "stop": None, "take": None}

    # Manage breakeven stop
    entry_price = state["entry_price"]
    entry_atr = state["entry_atr"]
    breakeven = state["breakeven"]

    if not breakeven:
        if direction == 1.0:
            profit_atr = (close - entry_price) / entry_atr
            if profit_atr >= 0.5:
                breakeven = True
                state["breakeven"] = True
        else:  # short
            profit_atr = (entry_price - close) / entry_atr
            if profit_atr >= 0.5:
                breakeven = True
                state["breakeven"] = True

    stop = entry_price if breakeven else None
    return {"target": pos, "stop": stop, "take": None}

import math
import numpy as np

def strategy(hist, state, pos, ind):
    # Compute 14-period RSI
    rsi = ind.rsi(hist.close, 14)
    if len(rsi) < 2:
        return {"target": pos, "stop": None, "take": None}
    rsi_curr = rsi[-1]
    rsi_prev = rsi[-2]

    # 4-hour trend filter: last completed 240-minute close vs its 50 EMA
    htf = hist.htf(240)
    trend_up = False
    trend_down = False
    if len(htf.close) >= 50:
        htf_close = htf.close
        ema50 = ind.ema(htf_close, 50)
        if len(ema50) > 0:
            last_htf_close = htf_close[-1]
            last_ema50 = ema50[-1]
            trend_up = last_htf_close > last_ema50
            trend_down = last_htf_close < last_ema50

    # ATR(14) for entry sizing and take profit
    atr = ind.atr(hist, 14)
    if len(atr) < 1:
        return {"target": pos, "stop": None, "take": None}
    current_atr = atr[-1]

    # Clear trade state when flat
    if pos == 0.0:
        for key in ('entry_price', 'entry_atr', 'direction', 'added'):
            if key in state:
                del state[key]

    # --- FLAT: look for entry signals ---
    if pos == 0.0:
        # Oversold bounce: RSI crosses above 25, 4h trend up
        if trend_up and rsi_prev <= 25 and rsi_curr > 25:
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = current_atr
            state['direction'] = 1
            state['added'] = False
            take = state['entry_price'] + 6 * state['entry_atr']
            return {"target": 0.5, "stop": None, "take": take}

        # Overbought fade: RSI crosses below 75, 4h trend down
        if trend_down and rsi_prev >= 75 and rsi_curr < 75:
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = current_atr
            state['direction'] = -1
            state['added'] = False
            take = state['entry_price'] - 6 * state['entry_atr']
            return {"target": -0.5, "stop": None, "take": take}

        return {"target": pos, "stop": None, "take": None}

    # --- IN A TRADE ---
    direction = state.get('direction', 0)
    if direction == 0:
        return {"target": pos, "stop": None, "take": None}

    # Opposite signal closes the trade immediately
    if direction == 1:
        if trend_down and rsi_prev >= 75 and rsi_curr < 75:
            return {"target": 0.0, "stop": None, "take": None}
    else:  # direction == -1
        if trend_up and rsi_prev <= 25 and rsi_curr > 25:
            return {"target": 0.0, "stop": None, "take": None}

    # Pyramid add: one half-size add when price moves 2 ATR in our favour
    added = state.get('added', False)
    if not added and abs(pos) == 0.5:
        entry_price = state['entry_price']
        entry_atr = state['entry_atr']
        if direction == 1:
            if hist.close[-1] >= entry_price + 2 * entry_atr:
                state['added'] = True
                take = entry_price + 6 * entry_atr
                return {"target": 1.0, "stop": None, "take": take}
        else:
            if hist.close[-1] <= entry_price - 2 * entry_atr:
                state['added'] = True
                take = entry_price - 6 * entry_atr
                return {"target": -1.0, "stop": None, "take": take}

    # Maintain position and take-profit level
    entry_price = state['entry_price']
    entry_atr = state['entry_atr']
    if direction == 1:
        take = entry_price + 6 * entry_atr
    else:
        take = entry_price - 6 * entry_atr

    return {"target": pos, "stop": None, "take": take}
